    'Import and export' => 'Import a export',
    'Import from WordPress' => 'Import z WordPressu',
    'File %s – site “%s” (%s). Nothing has been imported yet; this is only an overview of what the file contains.' => 'Soubor %s – web „%s“ (%s). Zatím se nic neimportovalo; tohle je jen přehled toho, co v souboru je.',
    'Posts' => 'Příspěvky',
