    'The file is not valid XML – it is damaged or incomplete. Download the export from WordPress again. The error is on line:' => 'Soubor není platné XML – je poškozený nebo neúplný. Stáhněte export z WordPressu znovu. Chyba je na řádku:',
    '(untitled)' => '(bez názvu)',
