    'Registered name and company ID' => 'Obchodní firma a IČO',
    'Fill in company details' => 'Vyplňte údaje o firmě',
    'Address, phone and opening hours appear on the contact page, in the footer and to search engines.' => 'Adresa, telefon a otevírací doba se ukážou na kontaktu, v patičce i vyhledávačům.',
    'Collections' => 'Kolekce',
    'New collection' => 'Nová kolekce',
    'No collections yet.' => 'Zatím žádné kolekce.',
    'A collection is a list of similar things with their own fields – testimonials, team members, products, branches, a price list. Put them on the site with the Collection list element in the builder; each item can also have its own page.' => 'Kolekce je seznam podobných věcí s vlastními poli – reference, členové týmu, produkty, pobočky, ceník. Na web je dostanete prvkem Výpis kolekce v builderu, každá položka může mít i vlastní stránku.',
    'Create a collection' => 'Založit kolekci',
    'Items' => 'Položek',
    'Item pages' => 'Stránky položek',
    'Add item' => 'Přidat položku',
    'Fields and settings' => 'Pole a nastavení',
    'Detail template' => 'Šablona detailu',
    'Detail template (%s)' => 'Šablona detailu (%s)',
    'Collection name' => 'Název kolekce',
    'e.g. Testimonials, Team, Products' => 'např. Reference, Tým, Produkty',
    'From the name if left empty. Item pages will then be at /address/item-name.' => 'Z názvu, když ji nevyplníte. Stránky položek pak budou na /adresa/nazev-polozky.',
    'each item has its own page (detail)' => 'každá položka má vlastní stránku (detail)',
    'Design the detail page in the builder (Detail template). Without a detail page, items are just cards in the list.' => 'Vzhled detailu navrhnete v builderu (Šablona detailu). Bez detailu jsou položky jen karty ve výpisu.',
    'Item fields' => 'Pole položek',
    'Every item always has a name. Add the fields you need – in the builder you insert them with a {{key}} tag. An empty label removes the field; the key of a saved field never changes.' => 'Každá položka má vždy název. Přidejte pole, která potřebujete – v builderu je vložíte značkou {{klíč}}. Prázdný popisek pole odebere; klíč už uloženého pole se nemění.',
    'created from the label' => 'vznikne z popisku',
    'Save collection' => 'Uložit kolekci',
    'Delete the collection with all its items? Lists on the site will disappear.' => 'Smazat kolekci i se všemi položkami? Výpisy na webu zmizí.',
    'Delete collection' => 'Smazat kolekci',
    'All collections' => 'Všechny kolekce',
    'The collection is empty.' => 'Kolekce je zatím prázdná.',
    'Add the first item – then put it on the site with the Collection list element in the builder.' => 'Přidejte první položku – na web ji pak dostanete prvkem Výpis kolekce v builderu.',
    'Address, order and visibility' => 'Adresa, pořadí a zobrazení',
    'Smaller number = earlier in the list.' => 'Menší číslo = dřív ve výpisu.',
