    'Design tokens (Figma, Tokens Studio)' => 'Design tokeny (Figma, Tokens Studio)',
    'Colours, fonts, sizes and typography styles in the W3C Design Tokens format (DTCG). A Kaleta export can be loaded back in full; from another tool the colours are taken.' => 'Barvy, písma, velikosti a typografické styly ve formátu W3C Design Tokens (DTCG). Export Kalety se dá načíst zpět celý, z jiného nástroje se převezmou barvy.',
    'Download tokens (.tokens.json)' => 'Stáhnout tokeny (.tokens.json)',
    'Load tokens? They will overwrite the appearance settings above.' => 'Načíst tokeny? Přepíší nastavení vzhledu výše.',
    'Tokens file' => 'Soubor s tokeny',
    'Load tokens' => 'Načíst tokeny',
    'The file contains no usable design tokens (a JSON file in the DTCG format is expected).' => 'Soubor neobsahuje design tokeny, které by šly použít (čekáme JSON ve formátu DTCG).',
    'Design tokens have been loaded.' => 'Design tokeny byly načteny.',
    'The enquiry form collects personal data – visitors must know how you handle it. The page is prepared as a hidden draft: fill in the details in square brackets and publish it.' => 'Formulář s poptávkou sbírá osobní údaje – návštěvník musí vědět, jak s nimi naložíte. Kostru stránky máte připravenou jako skrytou: doplňte údaje v hranatých závorkách a stránku zveřejněte.',
    'Always-on core: Pages, Collections, Media, Site appearance, Site parts, Menu, Components, Pop-ups, Users and roles, Import and export, Change log and Settings.' => 'Vždy zapnuté jádro: Stránky, Kolekce, Média, Vzhled webu, Části webu, Menu, Komponenty, Pop-up okna, Uživatelé a role, Import a export, Protokol změn a Nastavení.',
    'In the Claude app you do not need a token: add a custom connector with the address %s and confirm access by signing in.' => 'V aplikaci Claude token nepotřebujete: přidejte vlastní konektor s adresou %s a přístup potvrďte přihlášením.',
    'Enquiries and retention' => 'Poptávky a doba uchování',
    'Webhook to CRM' => 'Webhook do CRM',
    'Subscribers and export' => 'Odběratelé a export',
    'Choose languages' => 'Výběr jazyků',
    'Provider, key and model' => 'Poskytovatel, klíč a model',
    'How to connect Claude' => 'Jak připojit Clauda',
    'Links for an extension appear once it is switched on and saved.' => 'Odkazy u rozšíření se objeví po jeho zapnutí a uložení.',
    'Claude connection – how to connect' => 'Napojení na Claude – jak připojit',
    'In the Claude app open Settings → Connectors → Add custom connector.' => 'V aplikaci Claude otevřete Nastavení → Konektory → Přidat vlastní konektor.',
    'Enter this address:' => 'Jako adresu zadejte:',
    'Claude sends you here to sign in and confirm access. It then works with your account\'s permissions – builds and news are saved as drafts.' => 'Claude vás pošle sem přihlásit a potvrdit přístup. Pracuje pak s právy vašeho účtu – stavby a novinky ukládá jako koncept.',
    'In Claude Code, just run:' => 'V Claude Code stačí příkaz:',
    'Connected applications and personal tokens for other tools are in' => 'Připojené aplikace a osobní tokeny pro jiné nástroje najdete v',
    'The connector needs the site on HTTPS in the domain root.' => 'Konektor potřebuje web na HTTPS v kořeni domény.',
    'Administrator' => 'Správce',
    'Published pages' => 'Zveřejněné stránky',
