    'Logo, main colour and fonts.' => 'Logo, hlavní barva a písmo.',
    'Prepare your pages' => 'Připravte stránky',
    'About us, Services, Contact – and pick the home page in Settings.' => 'O nás, Služby, Kontakt – a v Nastavení vyberte, která bude úvodní.',
