    'A wrapper around the news item – a call to action or more news below the text, for example.' => 'Obálka kolem textu novinky – třeba výzva k akci nebo další novinky pod textem.',
    'Writes and edits their own news. An editor publishes them.' => 'Píše a upravuje vlastní novinky. Vydává je editor.',
    'Manages all site content – pages, news, media – and publishes.' => 'Spravuje veškerý obsah webu – stránky, novinky, média – a vydává.',
    '301 redirects from old addresses – essential after moving from another site.' => 'Správa přesměrování 301 ze starých adres – po přechodu z jiného webu nezbytné.',
    'A site in several languages: each further version (e.g. /cs/…) has its own pages, categories and news, a language switcher and hreflang tags. Pick the languages in Settings → General.' => 'Web ve více jazycích: každá další verze (/en/…) má své stránky, kategorie a novinky, přepínač jazyků a značky hreflang. Jazyky vyberete v Nastavení → Základní.',
    'An address from Make, Zapier, IFTTT or n8n. When a news item is published, the system sends it the title, lead, address and image – the service then shares it on Facebook, X, Mastodon, Slack and so on.' => 'Adresa ze služby Make, Zapier, IFTTT nebo n8n. Po vydání novinky na ni systém pošle titulek, perex, adresu a obrázek – služba je pak sama sdílí na Facebook, X, Mastodon, do Slacku apod.',
    'Recommended. Applies only to releases marked as security releases; you install regular versions yourself. The system checks for updates twice a day, backs up the database before installing and e-mails the result to the site e-mail.' => 'Doporučeno. Týká se jen vydání označených jako bezpečnostní; běžné verze instalujete sami. Systém se po novinkách dívá dvakrát denně, před instalací zálohuje databázi a o výsledku pošle e-mail na E-mail webu.',
    'Finished pages are served to visitors from memory – the site is faster and copes with traffic peaks. Leave it on.' => 'Hotové stránky se návštěvníkům podávají z paměti – web je rychlejší a vydrží nápor. Nechte zapnuté.',
    'Every news item also as plain text without navigation – for language models and AI search engines.' => 'Každá novinka i jako prostý text bez navigace – pro jazykové modely a AI vyhledávače.',
    'In the background, one news item every five minutes. The result is in News → Broken links.' => 'Na pozadí, jedna novinka za pět minut. Výsledek je v Novinky → Nefunkční odkazy.',
    'For example https://www.example.com, without a trailing slash. Links in e-mails, RSS, the sitemap and notifications are built from it. Change it after moving to another domain.' => 'Například https://www.firma.cz, bez lomítka na konci. Skládají se z ní odkazy v e-mailech, RSS, mapě webu a oznámeních. Po přestěhování na jinou doménu ji změňte.',
    'For example the registered company name and company ID.' => 'Například obchodní firma a IČO.',
    'News items per page' => 'Novinek na stránku',
    'Visitors see only the notice below. Signed-in users see the site as usual.' => 'Návštěvníci uvidí jen oznámení níže. Přihlášení uživatelé vidí web normálně.',
    'Visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Návštěvy, nejčtenější novinky a zdroje návštěv v sekci Statistika. Bez cookies a bez souhlasu.',
    'News table of contents from subheadings' => 'Obsah novinky z mezititulků',
    'Share links below the news item' => 'Odkazy pro sdílení pod novinkou',
    'Notify search engines about new news (IndexNow)' => 'Oznamovat nové novinky vyhledávačům (IndexNow)',
    'Similar news by tags and category is offered below a news item.' => 'Pod novinkou se nabídnou podobné podle štítků a kategorie.',
    'Empty = the site e-mail. With SMTP it must be an address your mailbox is allowed to send from.' => 'Prázdné = E-mail webu. U SMTP musí jít o adresu, ze které smí vaše schránka odesílat.',
    'Related news' => 'Související novinky',
    'News items with at least three subheadings get a clickable outline above the text.' => 'U novinek s aspoň třemi mezititulky se nad textem zobrazí klikací osnova.',
    'Webhook after publishing news' => 'Webhook po vydání novinky',
    'Plain-text news (.md)' => 'Čistá verze novinek (.md)',
    'Bodoni, Didot – elegance and fashion' => 'Bodoni, Didot – elegance a móda',
    'Helvetica, Arial – strong and confident' => 'Helvetica, Arial – výrazné a sebevědomé',
    'friendly, for services and family businesses' => 'přátelské, pro služby a rodinné firmy',
    'technology and development' => 'technologie a vývoj',
    'write and edit pages and news, and manage categories, collections and the look of the site.' => 'psát a upravovat stránky a novinky, spravovat kategorie, kolekce a vzhled webu.',
    'write and edit news.' => 'psát a upravovat novinky.',
    'no icon' => 'bez ikony',
    'Icon left of the text' => 'Ikona vlevo od textu',
    'Current item highlight' => 'Zvýraznění aktivní položky',
    'underline in the secondary colour' => 'podtržení doplňkovou barvou',
    'Site email' => 'E-mail webu',
    'Public email' => 'Veřejný e-mail',
    'With country code, e.g. +420 123 456 789.' => 'S předvolbou, např. +420 123 456 789.',
    'Contact for visitors and search engines. The site email from the General tab (where enquiries are sent) is not shown on the site.' => 'Kontakt pro návštěvníky a vyhledávače. E-mail webu ze záložky Základní (na ten chodí poptávky) se na webu neukazuje.',
    'Keep consent records (months)' => 'Uchovávat záznamy o souhlasech (měsíců)',
    'Older records are deleted automatically. 0 = keep.' => 'Starší záznamy se mažou automaticky. 0 = nemazat.',
    'Headings on phones' => 'Nadpisy na telefonu',
    'Headings on monitors' => 'Nadpisy na monitoru',
    'News author' => 'Autor novinek',
    'builder' => 'stavba',
    'News item saved. It will appear on the site once an editor publishes it.' => 'Novinka byla uložena. Na webu se objeví, až ji vydá editor.',
    '%s:1' => '%s : 1',
    'Account and tools' => 'Účet a nástroje',
    'News items need a category, so the category “%s” has been created. You can rename it or add more under News → Categories.' => 'Novinky potřebují kategorii, proto vznikla kategorie „%s“. Přejmenovat ji nebo přidat další můžete v Novinky → Kategorie.',
    'The file is larger than the server allows (%s at most). Make it smaller or ask your hosting provider to raise the limit.' => 'Soubor je větší, než server dovoluje nahrát (nejvýš %s). Zmenšete ho, nebo požádejte správce hostingu o vyšší limit.',
    'Awaiting publication' => 'Čekají na vydání',
    'awaiting publication' => 'čeká na vydání',
    'News authors cannot publish – review this news item and publish it.' => 'Autor novinek sám nevydává – novinku zkontrolujte a vydejte.',
    'News from authors awaiting publication' => 'Novinky od autorů čekají na vydání',
    'In your authenticator app (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) add a new account by scanning the QR code:' => 'V ověřovací aplikaci (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) přidejte nový účet naskenováním QR kódu:',
    'QR code for the authenticator app' => 'QR kód pro ověřovací aplikaci',
    'Cannot scan it? Add the account by typing the key:' => 'Nejde to naskenovat? Přidejte účet ručním zadáním klíče:',
    'page “%s”' => 'stránka „%s“',
    'collection detail “%s”' => 'detail kolekce „%s“',
    'component “%s”' => 'komponenta „%s“',
    'The component “%s” is used on: %s. Deleting it leaves an empty space there. Delete it anyway?' => 'Komponentu „%s“ používá: %s. Po smazání tam zůstane prázdné místo. Opravdu ji smazat?',
    'and %d more' => 'a %d dalších',
    'Add a description for blind visitors (alt text) to the images: what the image shows.' => 'U obrázků doplňte popis pro nevidomé (alt): co na obrázku je.',
    'The database update failed: %s. The site keeps running; install the fix in Settings → Backups and updates, or write to info@kaletacms.com.' => 'Aktualizace databáze se nepovedla: %s. Web běží dál; nainstalujte opravu v Nastavení → Zálohy a aktualizace, nebo napište na info@kaletacms.com.',
    'Border colour' => 'Barva rámečku',
    'preview shared' => 'sdílení náhledu',
    'Kaleta is free and has no ads.' => 'Kaleta je zdarma a bez reklam.',
    'Support its development on GitHub Sponsors' => 'Podpořte její vývoj na GitHub Sponsors',
    'Imprint (all details of the operator)' => 'Tiráž (všechny údaje o provozovateli)',
    'Imprint (legal notice)' => 'Tiráž (Impressum)',
    'Company identification number; in other countries its registration number.' => 'Identifikační číslo firmy; v jiné zemi její registrační číslo.',
    'Register court and entry, e.g. “Amtsgericht München, HRB 12345” or “Companies House, 01234567”. For the imprint.' => 'Soud a spisová značka, např. „Krajský soud v Brně, oddíl C, vložka 12345“ (v Německu Handelsregister). Pro tiráž.',
    'Who represents the company, e.g. “Managing director: Jane Smith” (Geschäftsführer). For the imprint.' => 'Kdo firmu zastupuje, např. „jednatel Jan Novák“ (Geschäftsführer). Pro tiráž.',
    'Texts for visitors (Search, Read more…) are translated into: %s. Other languages show them in English, with dates in their own format. You write the content of pages and news in the language of the version.' => 'Texty pro návštěvníky (Hledat, Číst dál…) jsou přeložené do jazyků: %s. Ostatní jazyky je mají anglicky, datum ve svém tvaru. Obsah stránek a novinek píšete v jazyce verze.',
    '%s: %s visits' => '%s: %s návštěv',
    'always dark' => 'vždy tmavý',
    'Switcher for visitors – in the header they choose light, dark or matching their device (the choice is remembered in their browser)' => 'Přepínač pro návštěvníky – v záhlaví si zvolí světlý, tmavý nebo vzhled podle zařízení (volba se pamatuje v jejich prohlížeči)',
    'Only items with the value (on an item page also {{field}} – related content)' => 'Jen položky s hodnotou (na stránce položky i {{pole}} – související obsah)',
    'Leave out the item being shown (related content on an item page)' => 'Vynechat zobrazenou položku (související obsah na stránce položky)',
    'Another window already uses the address “%s”.' => 'Adresu „%s“ už používá jiné okno.',
    'Pop-ups' => 'Pop-up okna',
    'The pop-up does not exist.' => 'Pop-up okno neexistuje.',
    'The pop-up needs a name.' => 'Okno musí mít název.',
    'The pop-up settings were saved.' => 'Nastavení okna bylo uloženo.',
    'Publish the pop-up in the builder first – then you can turn it on.' => 'Okno nejdřív publikujte v builderu – teprve pak ho jde zapnout.',
    'The pop-up counters were reset.' => 'Počitadla okna jsou vynulovaná.',
    'The pop-up was deleted.' => 'Pop-up okno bylo smazáno.',
    'The pop-up is off – it no longer shows on the site.' => 'Okno je vypnuté – na webu se už neukáže.',
    'The pop-up is on and shows on the site according to its rules.' => 'Okno je zapnuté a ukáže se na webu podle pravidel.',
    'New pop-up' => 'Nové pop-up okno',
    'No pop-ups yet.' => 'Zatím žádná pop-up okna.',
    'A window over the page for a newsletter sign-up, a download, an announcement or an offer. You build the content in the builder and set when and where it shows. The counters work without cookies.' => 'Okno přes stránku pro přihlášení k newsletteru, materiál ke stažení, oznámení nebo akci. Obsah poskládáte v builderu, v nastavení určíte, kdy a kde se ukáže. Počitadla fungují bez cookies.',
    'Create a pop-up' => 'Založit okno',
    'Pop-up' => 'Okno',
    'When it shows' => 'Kdy se ukáže',
    'Views' => 'Počet zobrazení',
    'Closes' => 'Zavření',
    'Language switcher' => 'Přepínač jazyků',
    'Choose the language version of the site – a row of codes or a dropdown (for example in the footer).' => 'Výběr jazykové verze webu – řada zkratek, nebo rozbalovací nabídka (třeba v patičce).',
    'dropdown' => 'rozbalovací nabídka',
    'codes in a row' => 'zkratky v řadě',
    'The dropdown opens' => 'Nabídka se otevře',
    'upwards (footer)' => 'nahoru (patička)',
    'downwards (header)' => 'dolů (záhlaví)',
    'Language switcher (turn it off when it is elsewhere, for example in the footer)' => 'Přepínač jazyků (vypněte, když je jinde, třeba v patičce)',
    'All pop-ups' => 'Všechna pop-up okna',
    'Conversions' => 'Konverze',
    'on the whole site' => 'na celém webu',
    'in selected places' => 'na vybraných místech',
    'A conversion is a form sent or a newsletter sign-up in the pop-up. The counters work without cookies and without any visitor data.' => 'Konverze je odeslaný formulář nebo přihlášení k odběru v okně. Počitadla fungují bez cookies a bez údajů o návštěvnících.',
    'Pop-up name' => 'Název okna',
    'e.g. Newsletter on the blog' => 'např. Newsletter na blogu',
    'Only for you in the admin and for screen readers. The address #popup-… is made from the name.' => 'Jen pro vás v administraci a pro čtečky obrazovky. Z názvu vznikne adresa #popup-…',
    'Start from' => 'Začít od',
    'The pop-up is created turned off and opens in the builder. It shows on the site once you publish it and turn it on.' => 'Okno se založí vypnuté a otevře se v builderu. Na webu se ukáže, až ho publikujete a zapnete.',
    'Edit the content in the builder' => 'Upravit obsah v builderu',
    'A link or button to #popup-%s opens the pop-up at any time – even when it does not show on its own.' => 'Odkaz nebo tlačítko s adresou #popup-%s okno otevře kdykoli – i když se samo neukazuje.',
    'When the pop-up shows' => 'Kdy se okno ukáže',
    'Trigger' => 'Spouštěč',
    'Trigger value' => 'Hodnota spouštěče',
    'Seconds for time and idle, percent of the page for scrolling, number of pages for the visit.' => 'Sekundy u času a nečinnosti, procenta stránky u rolování, počet stránek u návštěvy.',
    'Frequency' => 'Četnost',
    'number of days' => 'počet dní',
    'The visitor’s browser remembers it (sessionStorage and localStorage), not cookies.' => 'Pamatuje si to prohlížeč návštěvníka (sessionStorage a localStorage), ne cookies.',
    'Where the pop-up shows' => 'Kde se okno ukáže',
    'Places' => 'Místa',
    'only on selected pages, in collections or in news' => 'jen na vybraných stránkách, v kolekcích nebo v novinkách',
    'Collection item pages' => 'Stránky položek kolekcí',
    'the news list, categories and news items' => 'výpis novinek, kategorie a jednotlivé novinky',
    'from' => 'od',
    'to' => 'do',
    'Empty = no limit. Outside the period the pop-up is not added to the page at all.' => 'Prázdné = bez omezení. Mimo období se okno do stránky vůbec nevloží.',
    'Only from a campaign' => 'Jen z kampaně',
    'Text in the utm_* parameters of the address the visitor arrived with (e.g. spring or newsletter). Empty = everyone.' => 'Text v parametrech utm_* adresy, se kterou návštěvník přišel (např. jaro nebo newsletter). Prázdné = všichni.',
    'Only from a referrer' => 'Jen odkud přišel',
    'Part of the address of the site the visitor came from (e.g. facebook.com). Empty = from anywhere.' => 'Část adresy webu, ze kterého návštěvník přišel (např. facebook.com). Prázdné = odkudkoli.',
    'When several pop-ups would show, the lower number goes first. No pop-up opens over an open one.' => 'Když by se ukázalo víc oken, přednost má menší číslo. Přes otevřené okno se další neotevře.',
    'Reset the counters of views, closes and conversions?' => 'Vynulovat počitadla zobrazení, zavření a konverzí?',
    'Reset the counters' => 'Vynulovat počitadla',
    'Delete the pop-up? It disappears from the site at once.' => 'Smazat pop-up okno? Z webu zmizí hned.',
    'Delete the pop-up' => 'Smazat okno',
    'Window in the middle' => 'Okno uprostřed',
    'Slide-in panel in the corner' => 'Vysouvací panel v rohu',
    'Bar at the top' => 'Lišta nahoře',
    'Bar at the bottom' => 'Lišta dole',
    'Full screen' => 'Přes celou obrazovku',
    'After a number of seconds' => 'Po zadaném počtu sekund',
    'After scrolling part of the page' => 'Po odrolování části stránky',
    'When the visitor is about to leave' => 'Když se návštěvník chystá odejít',
    'After a number of seconds without activity' => 'Po zadaném počtu sekund nečinnosti',
    'After a number of pages in the visit' => 'Po zadaném počtu stránek v návštěvě',
    'Only by clicking a link or button' => 'Jen kliknutím na odkaz nebo tlačítko',
    'Once per visit' => 'Jednou za návštěvu',
    'Once every number of days' => 'Jednou za zadaný počet dní',
    'Until the visitor closes it' => 'Dokud ho návštěvník nezavře',
    'Until the visitor sends the form in it' => 'Dokud návštěvník neodešle formulář v okně',
    'Every time the trigger is met' => 'Pokaždé, když se spouštěč splní',
    'All devices' => 'Všechna zařízení',
    'Computer and tablet only' => 'Jen počítač a tablet',
    'Phone only' => 'Jen telefon',
    'A heading, a short text and an e-mail field with confirmed sign-up.' => 'Nadpis, krátký text a pole pro e-mail s potvrzením odběru.',
    'Download for an e-mail' => 'Materiál ke stažení za e-mail',
    'A guide or price list in exchange for contact details – the form goes to Enquiries.' => 'Nabídka průvodce nebo ceníku výměnou za kontakt – formulář jde do Poptávek.',
    'Announcement bar' => 'Oznamovací lišta',
    'A slim bar at the top with a short message and a link.' => 'Úzká lišta nahoře s krátkou zprávou a odkazem.',
    'Discount or offer' => 'Sleva nebo akce',
    'A bold offer with a code and a button.' => 'Výrazná nabídka s kódem a tlačítkem.',
    'Event invitation' => 'Pozvánka na událost',
    'A corner panel with the date, the place and a registration link.' => 'Panel v rohu s datem, místem a odkazem na registraci.',
    'Blank pop-up' => 'Prázdné okno',
    'A heading and a text – build the rest in the builder.' => 'Nadpis a text – zbytek poskládáte v builderu.',
    'Pop-up settings (when and where it shows)' => 'Nastavení okna (kdy a kde se ukáže)',
    'Collection fields and settings' => 'Pole a nastavení kolekce',
    '%d%%' => '%d %%',
    '%d subscribers are going to the mailing service; the site sends the rest gradually in the background.' => 'Do mailingové služby jde %d odběratelů; zbytek odešle web postupně na pozadí.',
    'The failed transfers were tried again – see the result in the Service column.' => 'Nepovedené přenosy se zkusily znovu – výsledek vidíte ve sloupci Služba.',
    'Confirmed subscribers go to %s automatically; those who unsubscribe are removed from it.' => 'Potvrzení odběratelé jdou automaticky do služby %s, odhlášení se z ní odebírají.',
    'Waiting to be sent: %d.' => 'Čeká na odeslání: %d.',
    'Failed: %d.' => 'Nepovedlo se: %d.',
    'Send all confirmed subscribers to the service' => 'Poslat do služby všechny potvrzené',
    'Try the failed ones again' => 'Zkusit nepovedené znovu',
    'Service settings' => 'Nastavení služby',
    'Using Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing? Once connected in Extensions, the site sends confirmed subscribers straight to your list.' => 'Používáte Brevo, MailerLite, Mailchimp, Ecomail nebo SmartEmailing? Po napojení v Rozšíření posílá web potvrzené odběratele rovnou do vašeho seznamu.',
    'Connect a service' => 'Napojit službu',
    'Service' => 'Služba',
    'waiting' => 'čeká',
    'The service did not respond.' => 'Služba neodpověděla.',
    'Newsletter – connection to a mailing service' => 'Newsletter – napojení na mailingovou službu',
    'Connection to a mailing service' => 'Napojení na mailingovou službu',
    'After a sign-up is confirmed (double opt-in), the site adds the address to the list in your service and removes it after unsubscribing. Sending, deliverability and unsubscribing from e-mails stay with the service. The transfer runs in the background – visitors do not wait.' => 'Po potvrzení odběru (double opt-in) přidá web adresu do seznamu ve vaší službě, po odhlášení ji odebere. Rozesílání, doručitelnost a odhlašování z e-mailů zůstávají u služby. Přenos běží na pozadí – návštěvník nečeká.',
    'none – you export subscribers to CSV' => 'žádná – odběratele exportujete do CSV',
    'Create the key in your service account (API, integrations). For SmartEmailing, enter the user name and the key separated by a colon. The key is stored only on your site and is never shown over MCP.' => 'Klíč vytvoříte v účtu služby (API, integrace). U SmartEmailingu zadejte uživatelské jméno a klíč oddělené dvojtečkou. Klíč se ukládá jen na vašem webu a přes MCP se neukazuje.',
    'The ID of the list (Brevo, Ecomail, SmartEmailing), group (MailerLite) or audience (Mailchimp) – you find it in the list settings in the service.' => 'ID seznamu (Brevo, Ecomail, SmartEmailing), skupiny (MailerLite) nebo audience (Mailchimp) – najdete ho v nastavení seznamu ve službě.',
    'Webhook URL' => 'Adresa webhooku',
    'Only for “Another service via a webhook”: the site sends JSON with the event novy_odberatel or odhlaseni_odberu and the e-mail.' => 'Jen u volby „Jiná služba přes webhook“: web pošle JSON s událostí novy_odberatel nebo odhlaseni_odberu a e-mailem.',
    'Another service via a webhook (Make, Zapier, n8n)' => 'Jiná služba přes webhook (Make, Zapier, n8n)',
    'Parts of the appearance' => 'Části vzhledu',
    'Styles' => 'Styly',
    'A style is a ready set of colours, fonts, sizes and corner radius. Pick one with a click and fine-tune it in the other tabs – the content of the site does not change.' => 'Styl je hotová sada barev, písem, velikostí a zaoblení. Vyberte ho jedním klikem a v dalších záložkách dolaďte – obsah webu se nemění.',
    'current' => 'aktuální',
    'You do not have to put a look for your brand together by hand: connect Claude and write, for example, “Set the look of the site to our brand – primary colour #0E6E6E, serif headings, subtle rounding”. It saves the colours and fonts to the design system, and you see the result here.' => 'Vzhled podle vaší značky nemusíte skládat ručně: připojte Clauda a napište mu třeba „Nastav vzhled webu podle naší značky – hlavní barva #0E6E6E, titulky patkovým písmem, jemné zaoblení“. Barvy a písma uloží do design systému, výsledek uvidíte tady.',
    'Buttons, cards, images and form fields across the site get this radius.' => 'Zaoblení dostanou tlačítka, karty, obrázky a pole formulářů na celém webu.',
    'Fonts and sizes' => 'Písmo a velikosti',
    'Shapes' => 'Tvary',
    'Kaleta installation' => 'Instalace Kalety',
    'Server check' => 'Kontrola serveru',
    'The server does not meet the requirements. Fix the items marked with a cross and reload the page.' => 'Server nesplňuje požadavky. Opravte položky označené křížkem a obnovte stránku.',
    'The installation could not be completed – check the highlighted fields.' => 'Instalaci se nepodařilo dokončit – zkontrolujte zvýrazněná pole.',
    'MySQL or MariaDB. Create an empty database beforehand – in your hosting control panel.' => 'MySQL nebo MariaDB. Prázdnou databázi založte předem – na hostingu v jeho administraci.',
    'Database name' => 'Název databáze',
    'Table prefix' => 'Předpona tabulek',
    'Site and administrator' => 'Web a administrátor',
    'The account you will first sign in to the administration with.' => 'Účet, kterým se poprvé přihlásíte do administrace.',
    'Scheduled news posts are published and dates are shown according to it.' => 'Podle něj se vydávají naplánované novinky a zobrazují data.',
    'Install Kaleta' => 'Nainstalovat Kaletu',
    'Creates the database tables and the config.php file.' => 'Vytvoří tabulky v databázi a soubor config.php.',
    'Kaleta is already installed' => 'Kaleta je už nainstalovaná',
    'The config.php file exists, so the installer changes nothing.' => 'Soubor config.php existuje, instalátor proto nic nemění.',
    'Done, your website is running' => 'Hotovo, web běží',
    'The database is ready and the configuration has been written.' => 'Databáze je připravena a konfigurace zapsána.',
    'For security reasons install.php has deleted itself – there is nothing else you need to do.' => 'Soubor install.php se z bezpečnostních důvodů smazal sám – nic dalšího dělat nemusíte.',
    'For security reasons, now delete this file from the server:' => 'Z bezpečnostních důvodů teď ze serveru smažte soubor',
    'Go to the administration' => 'Přejít do administrace',
    'connection to a MySQL / MariaDB database' => 'připojení k databázi MySQL / MariaDB',
    'working with accented text (UTF-8)' => 'práce s češtinou',
    'needed to create config.php' => 'kvůli vytvoření config.php',
    'logs and cache' => 'logy a cache',
    'Prefix: lowercase letters, digits and underscore, at most 16 characters (e.g. ka_).' => 'Předpona: malá písmena, číslice a podtržítko, nejvýše 16 znaků (např. ka_).',
    'Fill in the database name and user.' => 'Vyplňte název databáze a uživatele.',
