    'Shown next to the subject in the inbox. Optional.' => 'Zobrazí se vedle předmětu ve schránce. Nepovinné.',
    'Introduction' => 'Úvod',
    'Plain text; an empty line starts a new paragraph, web addresses become links.' => 'Prostý text; prázdný řádek začne nový odstavec, webové adresy se stanou odkazy.',
    'News in the e-mail' => 'Novinky v e-mailu',
    'the latest' => 'nejnovější',
    'news items at the time of sending' => 'novinky v okamžiku odeslání',
    'chosen news items' => 'vybrané novinky',
    'no news – only the introduction and the button' => 'bez novinek – jen úvod a tlačítko',
    'Chosen news items' => 'Vybrané novinky',
    'No published news items yet.' => 'Zatím žádné vydané novinky.',
    'Optional, for example “See all news” or “Book an appointment”.' => 'Nepovinné, například „Všechny novinky“ nebo „Objednat se“.',
    'Button link' => 'Odkaz tlačítka',
    'A path on the site (/contact) or a full https:// address.' => 'Cesta na webu (/kontakt) nebo celá adresa https://.',
    'The language of the footer texts and of the latest news items.' => 'Jazyk textů v patičce a nejnovějších novinek.',
    'Save and send a test to %s' => 'Uložit a poslat zkoušku na %s',
    'Preview of the e-mail' => 'Náhled e-mailu',
    'Send to subscribers' => 'Odeslat odběratelům',
    'Scheduled for %s – the latest news items are taken at that moment.' => 'Naplánováno na %s – nejnovější novinky se vezmou v tu chvíli.',
    'Cancel scheduling' => 'Zrušit naplánování',
    'Sending to subscribers needs the publishing permission – ask an editor or an administrator.' => 'Odeslání odběratelům vyžaduje právo vydávat – požádejte editora nebo správce.',
    'Send the newsletter to %d confirmed subscribers? Save your changes first – the saved version goes out.' => 'Odeslat newsletter %d potvrzeným odběratelům? Nejdřív uložte změny – odejde uložená verze.',
    'now' => 'hned',
    'at' => 'v',
    'Date and time of sending' => 'Datum a čas odeslání',
    'Send to %d subscribers' => 'Odeslat %d odběratelům',
    'The newsletter needs a subject.' => 'Newsletter potřebuje předmět.',
    'Choose at least one news item, or send the latest news.' => 'Vyberte aspoň jednu novinku, nebo pošlete nejnovější.',
    'The button link must be an https:// address or a path on the site starting with /.' => 'Odkaz tlačítka musí být adresa https:// nebo cesta na webu začínající lomítkem.',
    'The newsletter does not exist.' => 'Newsletter neexistuje.',
    'A newsletter that is being sent or was sent cannot be changed.' => 'Newsletter, který se odesílá nebo už odešel, nejde měnit.',
    'The newsletter is being sent right now – it cannot be deleted until it finishes.' => 'Newsletter se právě odesílá – smazat ho půjde, až odesílání skončí.',
    'The newsletter has already been sent.' => 'Newsletter už byl odeslán.',
    'There are no confirmed subscribers yet.' => 'Zatím nejsou žádní potvrzení odběratelé.',
    'The newsletter has no news items to send – publish a news item or choose No news.' => 'Newsletter nemá žádné novinky k odeslání – vydejte novinku, nebo zvolte Bez novinek.',
    'The time must be in the future, as YYYY-MM-DD HH:MM.' => 'Čas musí být v budoucnosti, ve tvaru RRRR-MM-DD HH:MM.',
    'The test address is not a valid e-mail.' => 'Adresa pro zkoušku není platný e-mail.',
    'Newsletters are sent only through an SMTP server (Brevo, Amazon SES, Mailgun, your mailbox…) – set it up in Settings → Mail.' => 'Newslettery se posílají jen přes SMTP server (Brevo, Amazon SES, Mailgun, vaše schránka…) – nastavte ho v Nastavení → Pošta.',
    'Cron has not called the tasks address in the last 30 minutes – newsletters go out in batches only while it runs. Set it up with the address in Settings → System status.' => 'Cron za posledních 30 minut nezavolal adresu úloh – newslettery odcházejí po dávkách, jen když běží. Nastavte ho s adresou v Nastavení → Stav systému.',
    'The newsletter was saved.' => 'Newsletter je uložený.',
    'Sending to subscribers needs the publishing permission.' => 'Odeslání odběratelům vyžaduje právo vydávat.',
    'The newsletter is scheduled for %s.' => 'Newsletter je naplánovaný na %s.',
    'Sending has started: %d subscribers. The e-mails go out in batches each time cron runs.' => 'Odesílání začalo: %d odběratelů. E-maily odcházejí po dávkách při každém běhu cronu.',
    'Scheduling was cancelled – the newsletter is a draft again.' => 'Naplánování je zrušené – newsletter je zase koncept.',
    'The newsletter was deleted.' => 'Newsletter je smazaný.',
    'Your account has no e-mail address – add one under My account.' => 'Váš účet nemá e-mailovou adresu – doplňte ji v Můj účet.',
    'The test e-mail went to %s.' => 'Zkušební e-mail odešel na %s.',
    'The test e-mail could not be sent: %s' => 'Zkušební e-mail se nepodařilo odeslat: %s',
    'Cron' => 'Cron',
    'not set up – scheduled work waits for visits, and newsletters cannot be sent; you will find the address further down this page' => 'nenastavený – naplánovaná práce čeká na návštěvy a newslettery nejde posílat; adresu najdete níž na této stránce',
    'last run %s – newsletters are not being sent until cron runs again' => 'naposledy %s – newslettery se neposílají, dokud cron znovu nepoběží',
    'Newsletters: e-mails per hour' => 'Newslettery: e-mailů za hodinu',
    'Newsletters go out in batches while cron runs. Keep to the sending limit of your SMTP service – free plans often allow only a few hundred e-mails a day.' => 'Newslettery odcházejí po dávkách, když běží cron. Držte se limitu vaší SMTP služby – bezplatné tarify často dovolí jen pár set e-mailů denně.',
    'Test' => 'Zkouška',
    'Deleted items stay here for 30 days, then they are deleted permanently.' => 'Smazané položky tu zůstanou 30 dní, pak se smažou natrvalo.',
    'Back to items' => 'Zpět na položky',
    'Items in the trash are not on the site. A restored item comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Položky v koši nejsou na webu. Obnovená položka se vrátí skrytá; po 30 dnech se z koše smaže natrvalo.',
    'Delete the item permanently? This cannot be undone.' => 'Smazat položku natrvalo? Nejde to vrátit.',
    'Move the item to the trash? It disappears from the site; you can restore it for 30 days.' => 'Přesunout položku do koše? Zmizí z webu; 30 dní ji můžete obnovit.',
    'The item is in the trash – it is no longer on the site; you can restore it for 30 days.' => 'Položka je v koši – na webu už není; 30 dní ji můžete obnovit.',
    'The item was restored as hidden.' => 'Položka je obnovená jako skrytá.',
    'The item was deleted permanently.' => 'Položka je smazaná natrvalo.',
    '%d enquiries read' => 'přečteno poptávek: %d',
    'Custom layout' => 'Vlastní šablona',
    '%s in the layout/ folder is no longer used – since 1.6 the look comes only from Site appearance and the builder. Move what you need into shared classes and site parts, then delete the folder.' => '%s ve složce layout/ se už nepoužívá – od verze 1.6 určuje vzhled jen Vzhled webu a builder. Co potřebujete, přeneste do sdílených tříd a částí webu a složku smažte.',
    'Unpublished look changes' => 'Nepublikované změny vzhledu',
    'visitors still see the published look.' => 'návštěvníci dál vidí publikovaný vzhled.',
    'Preview the whole site' => 'Náhled celého webu',
    'Publish the look' => 'Publikovat vzhled',
    'Discard the unpublished look changes?' => 'Zahodit nepublikované změny vzhledu?',
    'Design system: %s' => 'Design system: %s',
    'no change' => 'beze změny',
    'Classes: %s' => 'Třídy: %s',
    'changed' => 'změněná',
    'Menus: %s' => 'Menu: %s',
    'automatic' => 'automatické',
    'Saved to the draft look – preview the whole site, then publish it.' => 'Uloženo do konceptu vzhledu – prohlédněte si celý web a pak ho publikujte.',
    'There was nothing to publish.' => 'Nebylo co publikovat.',
    'The look is published: %s' => 'Vzhled je publikovaný: %s',
    'The unpublished look changes were discarded.' => 'Nepublikované změny vzhledu jsou zahozené.',
    'The earlier look is in the draft – preview the whole site, then publish it.' => 'Dřívější vzhled je v konceptu – prohlédněte si celý web a pak ho publikujte.',
    'The look version does not exist.' => 'Tato verze vzhledu neexistuje.',
    'Design tokens have been loaded into the draft look – preview the whole site, then publish it.' => 'Design tokeny jsou načtené do konceptu vzhledu – prohlédněte si celý web a pak ho publikujte.',
    'Colours, fonts, sizes and shapes go to the draft look first – with changes of shared classes and menus. Visitors see them once you publish the look.' => 'Barvy, písma, velikosti a tvary jdou nejdřív do konceptu vzhledu – spolu se změnami sdílených tříd a menu. Návštěvníci je uvidí, až vzhled publikujete.',
    'Earlier looks' => 'Dřívější vzhledy',
    'Each time you publish the look, the one before is kept here (the last 20).' => 'Při každém publikování vzhledu se sem uloží ten předchozí (posledních 20).',
    'before: %s' => 'před změnou: %s',
    'Back to this look' => 'Vrátit tento vzhled',
    'The menu is saved to the draft look – preview the whole site, then publish it.' => 'Menu je uložené v konceptu vzhledu – prohlédněte si celý web a pak ho publikujte.',
    'In the draft look the menu is again built automatically from pages in the navigation.' => 'V konceptu vzhledu se menu zase skládá automaticky ze stránek v navigaci.',
    'In the draft look the footer menu is empty.' => 'V konceptu vzhledu je menu v patičce prázdné.',
    '%s (dark mode)' => '%s (tmavý režim)',
    'Heading font' => 'Písmo nadpisů',
    'Text font' => 'Písmo textu',
    'Base font size' => 'Základní velikost písma',
    'Type scale' => 'Poměr velikostí písma',
    'Text width' => 'Šířka textu',
    'Custom fonts' => 'Vlastní písma',
    'Logo left, menu right' => 'Logo vlevo, menu vpravo',
    'The logo on the left, the menu and a button on the right. Stays at the top while scrolling.' => 'Logo vlevo, menu a tlačítko vpravo. Při posouvání zůstává nahoře.',
    'Centred logo' => 'Logo uprostřed',
    'The logo in the middle with the menu below it – for a site led by the brand.' => 'Logo uprostřed a pod ním menu – pro web, který stojí na značce.',
    'With a contact bar' => 'S kontaktní lištou',
    'A thin bar with the phone and e-mail above the logo and the menu.' => 'Tenká lišta s telefonem a e-mailem nad logem a menu.',
    'Minimal' => 'Minimální',
    'Only the logo and one button – for a campaign page without the menu.' => 'Jen logo a jedno tlačítko – pro kampaňovou stránku bez menu.',
    'Columns' => 'Sloupce',
    'The company, the footer menu, contacts and a newsletter sign-up, the copyright below.' => 'Firma, menu patičky, kontakty a přihlášení k odběru, pod tím copyright.',
    'Compact' => 'Kompaktní',
    'One line: the company name, the footer menu and the copyright.' => 'Jeden řádek: název firmy, menu patičky a copyright.',
    'With the imprint' => 'S tiráží',
    'The company details for the imprint next to the footer menu and social networks.' => 'Údaje o firmě pro tiráž vedle menu patičky a sociálních sítí.',
    'With a call to action' => 'S výzvou k akci',
    'A coloured call to action above a two-column footer.' => 'Barevná výzva k akci nad patičkou ve dvou sloupcích.',
    'The news item and a call to action below it.' => 'Novinka a pod ní výzva k akci.',
    'Plain' => 'Jednoduchá',
    'Only the news item.' => 'Jen novinka.',
    'Only the list of news.' => 'Jen výpis novinek.',
    'With a newsletter sign-up' => 'S přihlášením k odběru',
    'The list of news and a newsletter sign-up below it.' => 'Výpis novinek a pod ním přihlášení k odběru.',
    'Only the message and the links from the system.' => 'Jen hláška a odkazy od systému.',
    'With search' => 'S vyhledáváním',
    'The message with a search box below it.' => 'Hláška a pod ní vyhledávací pole.',
    'Templates: %s' => 'Šablony: %s',
    'Use this template' => 'Použít tuto šablonu',
    'All site parts' => 'Všechny části webu',
    'A template is a clean skeleton – colours, fonts and spacing come from your design system. It goes into the draft of the part: adjust it in the builder and publish it; until then visitors see the published version.' => 'Šablona je čistá kostra – barvy, písma a mezery si bere z vašeho design systému. Uloží se do konceptu části: upravte ji v builderu a publikujte; do té doby návštěvníci vidí publikovanou podobu.',
    'The template could not be used.' => 'Šablonu se nepodařilo použít.',
    'The template is in the draft – adjust it and publish; until then visitors see the published version.' => 'Šablona je v konceptu – upravte ji a publikujte; do té doby návštěvníci vidí publikovanou podobu.',
    'Webhooks' => 'Webhooky',
    'A webhook sends data to another service the moment something happens on the site – a new enquiry to a CRM or Slack, a published news item to Make, Zapier or n8n, which then share it on social networks.' => 'Webhook pošle data jiné službě ve chvíli, kdy se na webu něco stane – novou poptávku do CRM nebo Slacku, vydanou novinku do Make, Zapieru nebo n8n, které ji pak sdílejí na sociální sítě.',
    'Addresses' => 'Adresy',
    'Signature' => 'Podpis',
    'Signing secret' => 'Tajný klíč pro podpis',
    'Every call carries the headers X-Kaleta-Timestamp and X-Kaleta-Signature (sha256=HMAC-SHA256 of “timestamp.body” with this secret). A receiver that checks the signature knows the call came from your site and was not changed. Keep the secret private.' => 'Každé volání nese hlavičky X-Kaleta-Timestamp a X-Kaleta-Signature (sha256=HMAC-SHA256 z „časová značka.tělo“ s tímto klíčem). Příjemce, který podpis ověří, ví, že volání přišlo z vašeho webu a nikdo ho nezměnil. Klíč nikomu neukazujte.',
    'Create a new secret? Receivers that check the signature will reject calls until you give them the new one.' => 'Vytvořit nový klíč? Příjemci, kteří ověřují podpis, budou volání odmítat, dokud jim nový klíč nezadáte.',
    'Create a new secret' => 'Vytvořit nový klíč',
    'How to check the signature' => 'Jak ověřit podpis',
    'Send a test call' => 'Poslat zkušební volání',
    'Delivery log' => 'Protokol doručení',
    'No webhook has been sent yet.' => 'Zatím nebyl odeslán žádný webhook.',
    'Event' => 'Událost',
    'Address' => 'Adresa',
    'delivered' => 'doručeno',
    'not delivered' => 'nedoručeno',
    'Send again' => 'Poslat znovu',
    'A call that fails is retried after 1, 5 and 30 minutes and after 2 and 12 hours. Records are deleted after 30 days; the content of a delivered call is not kept.' => 'Nedoručené volání se zkusí znovu po 1, 5 a 30 minutách a po 2 a 12 hodinách. Záznamy se mažou po 30 dnech; obsah doručeného volání se neuchovává.',
    'First fill in and save at least one webhook address (https://).' => 'Nejdřív vyplňte a uložte aspoň jednu adresu webhooku (https://).',
    'The test call has been delivered.' => 'Zkušební volání bylo doručeno.',
    'The test call was not delivered – the reason is in the delivery log. It will be retried automatically.' => 'Zkušební volání se nepodařilo doručit – důvod je v protokolu doručení. Zkusí se znovu samo.',
    'A new secret has been created. Paste it into every receiver that checks the signature.' => 'Nový klíč je vytvořený. Vložte ho do každého příjemce, který ověřuje podpis.',
    'Only https:// addresses are allowed.' => 'Povolené jsou jen adresy https://.',
    'The receiver did not respond.' => 'Příjemce neodpověděl.',
    'Its classes and components were not imported – only an administrator can add them.' => 'Její třídy a komponenty se nenaimportovaly – přidat je může jen správce.',
    'New classes: %d, new components: %d (those the site already had were kept).' => 'Nové třídy: %d, nové komponenty: %d (ty, které web už měl, zůstaly beze změny).',
    'all calls of the last 7 days delivered' => 'všechna volání za posledních 7 dní doručena',
    '%d call(s) of the last 7 days not delivered – see Settings → Webhooks' => '%d volání za posledních 7 dní se nepodařilo doručit – viz Nastavení → Webhooky',
    'Import from Kaleta' => 'Import z Kalety',
    'Moving a site from another Kaleta installation: upload its export (the .zip archive from Export of the whole site). Everything is imported – pages, news, collections, components, menus, the look and the media – into a new, empty site; user accounts and secrets are never part of an export.' => 'Přesun webu z jiné instalace Kalety: nahrajte jeho export (archiv .zip z Exportu celého webu). Naimportuje se všechno – stránky, novinky, kolekce, komponenty, menu, vzhled i média – do nového, prázdného webu; uživatelské účty a tajné údaje v exportu nikdy nejsou.',
    'This site already has its own content, so an export cannot be imported here. Install Kaleta again and choose “Start from an export”.' => 'Tento web už má vlastní obsah, export sem proto naimportovat nejde. Nainstalujte Kaletu znovu a zvolte „Začít z exportu“.',
    'Kaleta export' => 'Export Kalety',
    'imported' => 'naimportováno',
    'Export of the site “%s” from Kaleta %s, created %s.' => 'Export webu „%s“ z Kalety %s, vytvořený %s.',
    'Files in media/' => 'Soubory v media/',
    'The export has no files – copy the media/ folder from the old site over FTP before or after the import.' => 'Export neobsahuje soubory – složku media/ ze starého webu zkopírujte přes FTP před importem nebo po něm.',
    'The import replaces all content of this site: pages, news, collections, components, menus, site parts, pop-ups, redirects and the media library, and takes over the site name, company details, languages and the look. User accounts, passwords, keys and the settings of mail and backups stay as they are on this site – the export never contains them. Imported news will be yours.' => 'Import nahradí veškerý obsah tohoto webu: stránky, novinky, kolekce, komponenty, menu, části webu, pop-upy, přesměrování a knihovnu médií, a převezme název webu, údaje o firmě, jazyky a vzhled. Uživatelské účty, hesla, klíče a nastavení pošty a záloh zůstanou tak, jak jsou na tomto webu – export je nikdy neobsahuje. Naimportované novinky budou vaše.',
    'This site already has its own content (pages: %d, news: %d, collection items: %d, media: %d). A Kaleta export can be imported only into a new, empty site – install Kaleta again and choose “Start from an export”.' => 'Tento web už má vlastní obsah (stránky: %d, novinky: %d, položky kolekcí: %d, média: %d). Export Kalety jde naimportovat jen do nového, prázdného webu – nainstalujte Kaletu znovu a zvolte „Začít z exportu“.',
    'Replace the content of this site with the export. A database backup is made first.' => 'Nahradit obsah tohoto webu exportem. Nejdřív se vytvoří záloha databáze.',
    'Import' => 'Importovat',
    'Copying files into media/: %s of %s. Keep this page open, it continues by itself.' => 'Kopírování souborů do media/: %s z %s. Nechte stránku otevřenou, pokračuje sama.',
    'The site has been imported.' => 'Web je naimportovaný.',
    '%d skipped' => '%d přeskočeno',
    'Files that could not be saved' => 'Soubory, které se nepodařilo uložit',
    'The state before the import is in backup %s (Settings → Backups and updates). Check the site, then delete the export file – it is no longer needed.' => 'Stav před importem je v záloze %s (Nastavení → Zálohy a aktualizace). Web zkontrolujte a pak soubor exportu smažte – už není potřeba.',
    'The state before the import is in backup %s (Settings → Backups and updates).' => 'Stav před importem je v záloze %s (Nastavení → Zálohy a aktualizace).',
    'Confirm that the content of this site will be replaced.' => 'Potvrďte, že se obsah tohoto webu nahradí.',
    'The site already has its own content. A Kaleta export can be imported only into a new, empty site.' => 'Web už má vlastní obsah. Export Kalety jde naimportovat jen do nového, prázdného webu.',
    'The file is not a Kaleta export.' => 'Soubor není export Kalety.',
    'The file is not a Kaleta export (obsah.json is missing in the archive).' => 'Soubor není export Kalety (v archivu chybí obsah.json).',
    'The export comes from a newer version of Kaleta – update this site first (Settings → Backups and updates).' => 'Export pochází z novější verze Kalety – nejdřív aktualizujte tento web (Nastavení → Zálohy a aktualizace).',
    'The PHP zip extension is missing on the server – upload obsah.json from the archive instead.' => 'Na serveru chybí rozšíření PHP zip – nahrajte místo archivu soubor obsah.json z něj.',
    'Collection items' => 'Položky kolekcí',
    'Shared classes' => 'Sdílené třídy',
    'Menus' => 'Menu',
    'News' => 'Novinky',
    'Backup %s is ready, but the media could not be copied: %s' => 'Záloha %s je hotová, ale média se nepodařilo zkopírovat: %s',
    'A backup on the same server as the site does not help if you lose the hosting. Each new database backup therefore uploads itself elsewhere, and the media/ folder is copied to the same place – only new and changed files, in the background.' => 'Záloha na stejném serveru jako web nepomůže, když přijdete o hosting. Každá nová záloha databáze se proto nahraje jinam a na stejné místo se kopíruje i složka media/ – jen nové a změněné soubory, na pozadí.',
    'Copy the media too' => 'Kopírovat i média',
    'Uploaded images and files go to the folder media/ of the same target. A file deleted on the site stays in the copy.' => 'Nahrané obrázky a soubory jdou do složky media/ na stejném místě. Soubor smazaný na webu v kopii zůstane.',
    'Media: the last attempt %s failed: %s' => 'Média: poslední pokus %s selhal: %s',
    'Media: the copy is complete (checked %s).' => 'Média: kopie je kompletní (kontrola %s).',
    'Media: %d files are still waiting – the copy continues in the background.' => 'Média: ještě čeká %d souborů – kopírování pokračuje na pozadí.',
    'Automatic backups' => 'Automatické zálohy',
    'Every day something changed on the site, otherwise once a week – while an administrator works in the administration or cron runs. The last 10 backups are kept.' => 'Každý den, kdy se na webu něco změnilo, jinak jednou týdně – když správce pracuje v administraci nebo běží cron. Uchovává se posledních 10 záloh.',
    'How to restore the site after losing the hosting' => 'Jak obnovit web po ztrátě hostingu',
    'Install Kaleta on the new hosting with the same table prefix (ka_ unless you changed it) and any starter site.' => 'Nainstalujte Kaletu na nový hosting se stejnou předponou tabulek (ka_, pokud jste ji neměnili) a s libovolným startovacím webem.',
    'Upload the latest database backup (kaleta-….sql.gz from your FTP or S3 copy, or a downloaded one) over FTP into storage/zalohy/.' => 'Nahrajte poslední zálohu databáze (kaleta-….sql.gz z kopie na FTP nebo S3, nebo staženou) přes FTP do storage/zalohy/.',
    'Copy the media/ folder from the same place into the root of the site.' => 'Zkopírujte složku media/ ze stejného místa do kořene webu.',
    'Here in Backups, click Restore at that backup. Then sign in with the accounts from the backup.' => 'Tady v Zálohách klikněte u té zálohy na Obnovit. Pak se přihlaste účty ze zálohy.',
    'Moving a site to another Kaleta installation without accounts and secrets is simpler with Export of the whole site and Import from Kaleta (Import and export).' => 'Přesun webu do jiné instalace Kalety bez účtů a tajných údajů je jednodušší přes Export celého webu a Import z Kalety (Import a export).',
    '%d visits in the last 30 days ended with “page not found” – add a redirect to the right page.' => '%d návštěv za posledních 30 dní skončilo „stránka nenalezena“ – přidejte přesměrování na správnou stránku.',
    'An item points at a page that no longer exists.' => 'Položka vede na stránku, která už neexistuje.',
    'Component “%s”' => 'Komponenta „%s“',
    'Item template of “%s”' => 'Šablona položky „%s“',
    'Item “%s” (%s)' => 'Položka „%s“ (%s)',
    'Menu “%s”' => 'Menu „%s“',
    'News item “%s”' => 'Novinka „%s“',
    'No description for search engines and no longer text to take one from.' => 'Chybí popis pro vyhledávače a není ani delší text, ze kterého by se vzal.',
    'No description for search engines – they then make up their own from the page text.' => 'Chybí popis pro vyhledávače – ty si pak vymyslí vlastní z textu stránky.',
    'Page “%s”' => 'Stránka „%s“',
    'Pop-up “%s”' => 'Pop-up okno „%s“',
    'Site part “%s”' => 'Část webu „%s“',
    'The item “%s” points at a hidden page – visitors do not see it in the menu.' => 'Položka „%s“ vede na skrytou stránku – návštěvníci ji v menu nevidí.',
    'The item “%s” points at a page in the trash.' => 'Položka „%s“ vede na stránku v koši.',
    'The link %s does not work (%s).' => 'Odkaz %s nefunguje (%s).',
    'The link %s leads to a page that does not exist.' => 'Odkaz %s vede na stránku, která neexistuje.',
    'The title “%s” is used %d times – search engines cannot tell the pages apart.' => 'Titulek „%s“ je použitý %d× – vyhledávače stránky od sebe nerozliší.',
    'no response' => 'bez odpovědi',
    'External links are checked in the background, one news item every five minutes. The audit runs each time you open this page.' => 'Externí odkazy se kontrolují na pozadí, jedna novinka každých pět minut. Audit proběhne pokaždé, když tuto stránku otevřete.',
    'Found %d things to fix. Each one links to where you fix it; Claude can go through them too (site_audit).' => 'Nalezeno %d věcí k opravě. U každé je odkaz, kde ji opravíte; projít je umí i Claude (site_audit).',
    'No problems found – links lead where they should, pages have descriptions and the builder checks pass.' => 'Žádné problémy – odkazy vedou, kam mají, stránky mají popisy a kontroly builderu prošly.',
    'Show on the site' => 'Zobrazit na webu',
    'A three-letter code (EUR, CZK, USD). Without it the price is not passed on.' => 'Třípísmenný kód (EUR, CZK, USD). Bez něj se cena nepředá.',
    'Currency of the price' => 'Měna ceny',
    'Items are' => 'Položky jsou',
    'Structured data for search engines' => 'Strukturovaná data pro vyhledávače',
    'Tell search engines what the items are. Item pages then carry the schema.org data; the name, address, description and image come from the item itself. Save new fields first – then you can pick them here.' => 'Řekněte vyhledávačům, co položky jsou. Stránky položek pak ponesou data schema.org; název, adresa, popis a obrázek se berou z položky. Nová pole nejdřív uložte – pak je tu půjde vybrat.',
    'nothing specific (no structured data)' => 'nic konkrétního (bez strukturovaných dat)',
    '– none –' => '– žádné –',
    'Item history (%s)' => 'Historie položky (%s)',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the first longer text field.' => 'Jedna dvě věty do výsledků hledání (do 160 znaků). Prázdné = začátek prvního delšího textového pole.',
    'Publish the hidden item automatically at:' => 'Zveřejnit skrytou položku automaticky:',
    'Restore this version of the item? The current version stays in the history.' => 'Obnovit tuto verzi položky? Současná verze zůstane v historii.',
    'The item page stays reachable, but it is left out of search engines, the sitemap, llms.txt and site search.' => 'Stránka položky zůstane dostupná, ale vynechá se z vyhledávačů, mapy webu, llms.txt i hledání na webu.',
    'empty = the first image field' => 'prázdné = první obrázkové pole',
    'empty = the item name' => 'prázdné = název položky',
    'Missing descriptions' => 'Chybějící popisy',
    'Duplicate titles' => 'Stejné titulky',
    'Buttons, images and headings' => 'Tlačítka, obrázky a nadpisy',
    'Frequent 404 errors' => 'Časté chyby 404',
    'Product' => 'Produkt',
    'Question and answer' => 'Otázka a odpověď',
    'Kind of service' => 'Druh služby',
    'Area served' => 'Oblast působnosti',
    'Price' => 'Cena',
    'Job title' => 'Pracovní pozice',
    'Profile link' => 'Odkaz na profil',
    'Brand' => 'Značka',
    'Product code (SKU)' => 'Kód produktu (SKU)',
    'Start' => 'Začátek',
    'End' => 'Konec',
    'Place' => 'Místo',
    'Site audit' => 'Audit webu',
    'The earlier version of the item is back; the one before it is in the history.' => 'Dřívější verze položky je zpět; ta předchozí zůstala v historii.',
    'The media are too large to pack in one go. Turn on the off-site copy (it copies the media bit by bit) or download the media/ folder over FTP.' => 'Média jsou příliš velká na zabalení najednou. Zapněte kopie mimo server (média kopírují postupně), nebo složku media/ stáhněte přes FTP.',
    'The item is in the trash. Bring it back with restore_from_trash first.' => 'Položka je v koši. Nejdřív ji vraťte přes restore_from_trash.',
    'Addresses on your site that repeatedly ended with “page not found” this week: %d. Visitors came from an old link or a typo – send each one to the right page with a redirect, or ignore it.' => 'Adresy na vašem webu, které tento týden opakovaně skončily „stránka nenalezena“: %d. Návštěvníci přišli ze starého odkazu nebo s překlepem – každou pošlete přesměrováním na správnou stránku, nebo ji ignorujte.',
    'Review the addresses' => 'Projít adresy',
    'Ignore all' => 'Ignorovat vše',
    'Ignore' => 'Ignorovat',
    '%d addresses ignored. A new address that visitors cannot find will show up again.' => 'Ignorováno adres: %d. Nová adresa, kterou návštěvníci nenajdou, se znovu ukáže.',
    'Nothing to do – no address ended with “page not found” repeatedly in the last 60 days.' => 'Nic k řešení – za posledních 60 dní žádná adresa opakovaně neskončila „stránka nenalezena“.',
    'Visitors came to these addresses and found nothing – usually an old link from another site, a search engine or a typo. For each one choose:' => 'Návštěvníci na těchto adresách nic nenašli – obvykle jde o starý odkaz z jiného webu, z vyhledávače nebo o překlep. U každé zvolte:',
    'Redirect – the old address leads to the page that replaced it (the form above is filled in, add the target).' => 'Přesměrovat – stará adresa povede na stránku, která ji nahradila (formulář nahoře se vyplní, doplňte cíl).',
    'Ignore – nothing replaces it, or it is a bot probing for other systems. It will not come back.' => 'Ignorovat – nic ji nenahrazuje, nebo je to robot, který zkouší adresy jiných systémů. Už se nevrátí.',
    'Ignore all these addresses? The warning on the start screen goes away until a new address appears.' => 'Ignorovat všechny tyto adresy? Upozornění na úvodní obrazovce zmizí, dokud se neobjeví nová adresa.',
    'Security contact' => 'Kontakt pro bezpečnostní hlášení',
    'An e-mail address or an https:// page where people report security problems of this site. It is published at /.well-known/security.txt (RFC 9116); empty = no file.' => 'E-mailová adresa nebo stránka https://, kam lidé hlásí bezpečnostní problémy tohoto webu. Zveřejní se v /.well-known/security.txt (RFC 9116); prázdné = soubor nevznikne.',
    'What may Claude do?' => 'Co smí Claude dělat?',
    'Everything your account may do' => 'Vše, co smí váš účet',
    'Build, edit and publish with the permissions of your role (%s). The menu and the look still wait in the draft look until they are published.' => 'Stavět, upravovat a zveřejňovat s oprávněními vaší role (%s). Menu a vzhled i tak počkají v konceptu vzhledu, dokud se nezveřejní.',
    'Drafts only' => 'Jen koncepty',
    'Claude builds pages, writes news drafts and prepares look changes – you publish them. Nothing on the live site changes without you.' => 'Claude staví stránky, píše koncepty novinek a připravuje změny vzhledu – zveřejníte je vy. Bez vás se na webu nic nezmění.',
    'Read only' => 'Jen čtení',
    'Claude reads pages, settings, the audit and the change log, and suggests changes. It changes nothing.' => 'Claude čte stránky, nastavení, audit a protokol změn a navrhuje úpravy. Nic nemění.',
    'It will act with your account %s (%s) – never with more than your role allows.' => 'Bude pracovat s vaším účtem %s (%s) – nikdy s víc, než dovoluje vaše role.',
    'full access' => 'plný přístup',
    'drafts only' => 'jen koncepty',
    'read only' => 'jen čtení',
    'Made by:' => 'Provedl:',
    'people and Claude' => 'lidé i Claude',
    'people in the admin' => 'lidé v administraci',
    'Made by Claude through the connection %s' => 'Provedl Claude přes napojení %s',
    'Connect Claude' => 'Připojte Clauda',
    'Build and edit the site by talking to Claude. In the Claude app, add a custom connector with your site address followed by /mcp – My account shows the exact address.' => 'Stavějte a upravujte web v rozhovoru s Claudem. V aplikaci Claude přidejte vlastní konektor s adresou webu a /mcp na konci – přesnou adresu ukáže Můj účet.',
    'Claude sends you here to sign in. You choose what it may do: everything your account may, only save drafts, or only read.' => 'Claude vás pošle sem k přihlášení. Vyberete, co smí: vše, co smí váš účet, jen ukládat koncepty, nebo jen číst.',
    'The connector needs the site on HTTPS. In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'Konektor potřebuje web na HTTPS. V podsložce si aplikace Claude přihlášení najde sama; nástroji, který to neumí, dejte osobní token.',
    'Instructions for Claude' => 'Pokyny pro Clauda',
    'e.g. We address customers informally. Say “renovation”, never “reconstruction”. Keep headings short. Always offer a free visit.' => 'např. Zákazníkům tykáme. Píšeme „renovace“, nikdy „rekonstrukce“. Nadpisy krátce. Vždy nabídněte návštěvu zdarma.',
    'Brand voice, words to use or avoid, house rules. Every Claude connection gets them when it connects, and they are its resource kaleta://instructions.' => 'Tón značky, slova, která používat a kterým se vyhnout, pravidla domu. Každé napojení Clauda je dostane při připojení a má je jako zdroj kaleta://instructions.',
    'Remember where leads came from' => 'Pamatovat si, odkud poptávky přišly',
    'The first page of a visit, its campaign and the site that sent the visitor go with enquiries and newsletter sign-ups (Statistics → Campaigns and pages). Only for visitors who allow marketing in the cookie bar – turning it on adds that choice to the bar.' => 'První stránka návštěvy, její kampaň a web, ze kterého návštěvník přišel, se uloží k poptávkám a přihláškám k odběru (Statistiky → Kampaně a stránky). Jen u návštěvníků, kteří v cookie liště povolí marketing – zapnutím se tato volba do lišty přidá.',
    'Leads (enquiries and sign-ups)' => 'Zájemci (poptávky a přihlášky)',
    'Visits that became a lead' => 'Návštěvy, ze kterých byl zájemce',
    '%s leads' => 'zájemci: %s',
    'Pages that bring leads' => 'Stránky, které přinášejí zájemce',
    'Enquiries / sign-ups' => 'Poptávky / přihlášky',
    'Conversion' => 'Konverze',
    'Campaigns' => 'Kampaně',
    'Campaign (source / medium / name)' => 'Kampaň (zdroj / médium / název)',
    'No visits from links with utm parameters yet.' => 'Zatím žádné návštěvy z odkazů s parametry utm.',
    'First pages of visits that brought a lead' => 'První stránky návštěv, ze kterých byl zájemce',
    'Known only for visitors who allowed marketing cookies in the cookie bar.' => 'Známé jen u návštěvníků, kteří v cookie liště povolili marketing.',
    'Site' => 'Web',
    'Devices' => 'Zařízení',
    'Device' => 'Zařízení',
    'Computer' => 'Počítač',
    'The site has no pop-ups.' => 'Web nemá žádná pop-up okna.',
    'News item' => 'Novinka',
    'Pop-up counters run since the pop-up was made or reset. Claude reads the same report with get_stats.' => 'Počitadla pop-up oken běží od jejich vytvoření nebo vynulování. Claude čte stejný přehled nástrojem get_stats.',
    'inactive' => 'neaktivní',
    'First page of the visit' => 'První stránka návštěvy',
    'Came from' => 'Přišel z',
    'several choices (checkboxes)' => 'více možností (zaškrtávací políčka)',
    'hidden value (e.g. the product the form is about)' => 'skrytá hodnota (např. produkt, kterého se formulář týká)',
    'Options to tick (one per line)' => 'Možnosti k zaškrtnutí (jedna na řádek)',
    'Value sent with the form (not shown to the visitor)' => 'Hodnota odeslaná s formulářem (návštěvník ji nevidí)',
    'Paste the address of a Calendly or Google booking page, a Google, Microsoft, Tally, Typeform or Airtable form, or a Spotify or SoundCloud track.' => 'Vložte adresu rezervační stránky Calendly nebo Google, formuláře Google, Microsoft, Tally, Typeform či Airtable, nebo skladby ze Spotify či SoundCloudu.',
    'Embed' => 'Vložení',
    'A booking calendar, form or player from Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify or SoundCloud – loads after a click.' => 'Rezervační kalendář, formulář nebo přehrávač z Calendly, Googlu, Microsoft Forms, Tally, Typeformu, Airtable, Spotify nebo SoundCloudu – načte se po kliknutí.',
    'Address of the booking page, form or track (copied from the service)' => 'Adresa rezervační stránky, formuláře nebo skladby (zkopírovaná ze služby)',
    'What it is, for screen readers (e.g. Book a consultation)' => 'Co to je, pro čtečky obrazovky (např. Rezervace konzultace)',
    'player (160 px)' => 'přehrávač (160 px)',
    'small (450 px)' => 'malé (450 px)',
    'medium (700 px)' => 'střední (700 px)',
    'large (950 px)' => 'velké (950 px)',
    'Show: %s' => 'Zobrazit: %s',
    'Loads from %s after a click.' => 'Po klepnutí se načte z %s.',
    'Open in %s' => 'Otevřít v %s',
    '%s from %s' => '%s z %s',
    'Booking calendar' => 'Rezervační kalendář',
    'Form or table' => 'Formulář nebo tabulka',
    'Player' => 'Přehrávač',
    'Code in the head of this page' => 'Kód v hlavičce této stránky',
    'Only for this page, after the code for the whole site (Settings → Analytics) – e.g. the conversion tag of a landing page. Mind the cookie consent: code that tracks visitors belongs in the marketing code.' => 'Jen pro tuto stránku, za kódem pro celý web (Nastavení → Analytika) – např. konverzní značka vstupní stránky. Pozor na souhlas s cookies: kód, který sleduje návštěvníky, patří do marketingového kódu.',
    'Code in the head of a page can be set only by an administrator, through a connection with full access.' => 'Kód v hlavičce stránky smí nastavit jen správce, a to přes napojení s plným přístupem.',
    'Accessibility' => 'Přístupnost',
    ' (dark mode)' => ' (tmavý režim)',
    '%s has a contrast of %s : 1 – text needs at least 4.5 : 1.' => '%s má kontrast %s : 1 – text potřebuje aspoň 4,5 : 1.',
    'The whole site' => 'Celý web',
    'No accessibility statement – the European Accessibility Act expects a service to say how accessible it is and whom to contact about barriers. Add a page such as /accessibility.' => 'Chybí prohlášení o přístupnosti – evropský akt o přístupnosti (EAA) čeká, že služba řekne, jak je přístupná a na koho se obrátit kvůli bariérám. Přidejte stránku např. /pristupnost.',
    'The button “%s” does not say what it does – screen readers read buttons and links on their own.' => 'Tlačítko „%s“ neříká, co dělá – čtečky obrazovky čtou tlačítka a odkazy samostatně.',
    'An image in the text has no description for blind visitors (alt).' => 'Obrázek v textu nemá popis pro nevidomé (alt).',
    'A link has no text – a screen reader has nothing to read.' => 'Odkaz nemá text – čtečka obrazovky nemá co přečíst.',
    'The link “%s” does not say where it leads – screen readers read links on their own.' => 'Odkaz „%s“ neříká, kam vede – čtečky obrazovky čtou odkazy samostatně.',
    'A table has no header cells (th) – screen readers cannot tell what the columns mean.' => 'Tabulka nemá záhlaví (th) – čtečky obrazovky nepoznají, co sloupce znamenají.',
    'An embedded frame (iframe) has no title.' => 'Vložený rámec (iframe) nemá titulek.',
    'Start from a ready-made role:' => 'Začněte hotovou rolí:',
    'Client' => 'Klient',
    'Edits pages, news and collection items, answers enquiries and sees the statistics – the look, settings and users stay with the agency.' => 'Upravuje stránky, novinky a položky kolekcí, vyřizuje poptávky a vidí statistiky – vzhled, nastavení a uživatelé zůstávají agentuře.',
    'Writer' => 'Autor textů',
    'Writes news for someone else to publish.' => 'Píše novinky, které zveřejní někdo jiný.',
    'Enquiries only' => 'Jen poptávky',
    'Handles enquiries from the site forms and the newsletter subscribers.' => 'Vyřizuje poptávky z formulářů webu a odběratele newsletteru.',
    'Built and looked after by' => 'Web postavil a stará se o něj',
    'The agency or freelancer who looks after the site. The sign-in screen and the foot of the admin show whom to ask for help.' => 'Agentura nebo freelancer, který se o web stará. Přihlašovací obrazovka a spodní okraj administrace ukážou, na koho se obrátit s pomocí.',
    'Name' => 'Název',
    'E-mail for help' => 'E-mail pro pomoc',
    'Phone for help' => 'Telefon pro pomoc',
    'A path from Media, e.g. media/2026/10/agency.svg – click the file in Media to open it, its address starts with media/.' => 'Cesta z Médií, např. media/2026/10/agentura.svg – soubor otevřete kliknutím v Médiích, jeho adresa začíná media/.',
    'Website by %s' => 'Web spravuje %s',
    'help: %s' => 'pomoc: %s',
    'Before handing over' => 'Před předáním',
    'No site e-mail: enquiries and password resets have nowhere to go.' => 'Chybí e-mail webu: poptávky a obnovy hesla nemají kam jít.',
    'E-mail goes out through the host’s mail() – set an SMTP server so enquiries and newsletters do not end up in spam.' => 'E-maily odcházejí přes mail() hostingu – nastavte SMTP server, ať poptávky a newslettery nekončí ve spamu.',
    'Backups stay on the same server – add an off-site copy (FTPS or S3) in case the hosting is lost.' => 'Zálohy zůstávají na stejném serveru – přidejte kopii mimo server (FTPS nebo S3) pro případ ztráty hostingu.',
    'Company details are missing – the footer, the imprint and search engines use them.' => 'Chybí údaje o firmě – používá je patička, tiráž i vyhledávače.',
    'Search engines are blocked – switch indexing on when the site goes live.' => 'Vyhledávače jsou zablokované – při spuštění webu zapněte indexování.',
    'No site icon (favicon) – browsers and phones show a blank one.' => 'Chybí ikona webu (favicon) – prohlížeče a telefony ukážou prázdnou.',
    'Analytics or marketing codes run without a cookie bar – visitors in the EU must consent first.' => 'Kódy analytiky nebo marketingu běží bez cookie lišty – návštěvníci v EU musí nejdřív souhlasit.',
    'No security contact – add who takes reports of security problems (published as security.txt).' => 'Chybí kontakt pro bezpečnostní hlášení – doplňte, kdo přijímá hlášení bezpečnostních problémů (zveřejní se jako security.txt).',
    'The administrator %s signs in without two-step sign-in or a passkey.' => 'Správce %s se přihlašuje bez dvoufázového ověření i bez přístupového klíče.',
    'The client has no account of their own yet – create one with the Client role (Users → Roles).' => 'Klient zatím nemá vlastní účet – založte mu ho s rolí Klient (Uživatelé → Role).',
    'Your contact is not set – the client will not see whom to ask (Settings → General → Built and looked after by).' => 'Chybí váš kontakt – klient neuvidí, na koho se obrátit (Nastavení → Obecné → Web postavil a stará se o něj).',
    'Background tasks have never run – newsletters are sent only while they do. Add the cron line from System status.' => 'Úlohy na pozadí ještě neběžely – newslettery se odesílají jen tehdy. Přidejte řádek pro cron ze Stavu systému.',
    'How to use this' => 'Jak s tím pracovat',
    'guide, opens in a new tab' => 'návod, otevře se v nové záložce',
    'Could not connect to the SMTP server %s. Check the address, port and encryption; some hosts block outgoing SMTP.' => 'Nepodařilo se připojit k SMTP serveru %s. Zkontrolujte adresu, port a šifrování; některé hostingy odchozí SMTP blokují.',
    'The SMTP server refused the sign-in – check the user name and password (Gmail and Seznam need an app password).' => 'SMTP server odmítl přihlášení – zkontrolujte jméno a heslo (u Gmailu a Seznamu je potřeba „heslo pro aplikace“).',
    'SMTP server reply to %s: %s' => 'Odpověď SMTP serveru na %s: %s',
    'A scheduled newsletter can be changed only by someone who may send newsletters – unschedule it first.' => 'Naplánovaný newsletter může měnit jen ten, kdo smí newslettery odesílat – nejdřív zrušte naplánování.',
    'Without the extra spam check (CAPTCHA from Settings → Privacy and cookies)' => 'Bez dodatečné kontroly spamu (CAPTCHA z Nastavení → Soukromí a cookies)',
    'Spam check for forms' => 'Kontrola spamu ve formulářích',
    'Forms are protected without one: a signed time, a hidden trap field and a limit per address. Add a CAPTCHA only if spam still gets through. The provider receives the visitor’s address and browser details – name it in your privacy policy.' => 'Formuláře jsou chráněné i bez ní: podepsaný čas, skryté pole na roboty a limit na adresu. CAPTCHA přidejte, jen když spam pořád prochází. Poskytovatel dostane adresu a údaje o prohlížeči návštěvníka – uveďte ho v zásadách ochrany osobních údajů.',
    'Extra spam check' => 'Dodatečná kontrola spamu',
    'none – the built-in protection only' => 'žádná – jen vestavěná ochrana',
    'hCaptcha and Cloudflare Turnstile suit EU sites; reCAPTCHA v3 is invisible and scores every visit.' => 'hCaptcha a Cloudflare Turnstile se hodí pro weby v EU; reCAPTCHA v3 je neviditelná a hodnotí každou návštěvu.',
    'Site key' => 'Klíč webu',
    'From the provider’s dashboard, for this site’s domain.' => 'Z administrace poskytovatele, pro doménu tohoto webu.',
    'Secret key' => 'Tajný klíč',
    'the key is saved – enter a new one only to change it' => 'klíč je uložený – nový zadejte, jen když ho chcete změnit',
    'Stays on your site; Claude cannot read it.' => 'Zůstává na vašem webu; Claude ho nepřečte.',
    'Remove the saved key' => 'Odebrat uložený klíč',
    'Accept forms when the provider is down' => 'Přijmout formuláře, když poskytovatel neodpovídá',
    'The built-in protection still applies. Off = such forms are refused until the provider answers again.' => 'Vestavěná ochrana platí dál. Vypnuto = takové formuláře se odmítnou, dokud poskytovatel znovu neodpoví.',
    'The container ID in the form GTM-XXXXXXX. Consent mode is built in: with the built-in cookie bar the container starts after the visitor allows analytics or marketing.' => 'ID kontejneru ve tvaru GTM-XXXXXXX. Režim souhlasu je vestavěný: s vestavěnou cookie lištou se kontejner spustí, až návštěvník povolí analytické nebo marketingové cookies.',
    'Google Analytics is set here and probably also in your Tag Manager container – visits would be counted twice. Keep it in one place.' => 'Google Analytics je nastavené tady a nejspíš i v kontejneru Tag Manageru – návštěvy by se počítaly dvakrát. Nechte ho jen na jednom místě.',
    'Kaleta sends these events to the data layer for your tags: generate_lead (a form was sent), sign_up (newsletter), popup_conversion, click_phone, click_email and file_download.' => 'Kaleta posílá do datové vrstvy pro vaše značky tyto události: generate_lead (odeslaný formulář), sign_up (newsletter), popup_conversion, click_phone, click_email a file_download.',
    'Download a container template with these triggers' => 'Stáhnout šablonu kontejneru s těmito spouštěči',
    'This is switched off in the public demo. Install Kaleta to try it.' => 'Ve veřejném demu je tohle vypnuté. Vyzkoušíte to po instalaci Kalety.',
    'This is the public demo of Kaleta. Sign in as %s with the password %s. Everything you change disappears at the next hourly reset.' => 'Tohle je veřejné demo Kalety. Přihlaste se jako %s s heslem %s. Všechno, co změníte, zmizí při příštím obnovení, které probíhá každou hodinu.',
    'Public demo: everything you change here is reset in %s minutes. E-mail, imports, updates, users and the Claude connection are switched off.' => 'Veřejné demo: všechno, co tu změníte, se za %s minut obnoví. E-maily, importy, aktualizace, uživatelé a napojení Clauda jsou vypnuté.',
    'Sending e-mail is switched off in the public demo.' => 'Ve veřejném demu se e-maily neposílají.',
    'Downloading from other sites is switched off in the public demo.' => 'Ve veřejném demu se z jiných webů nic nestahuje.',
    'Import from a website' => 'Import z webu',
    'Enter the address of a site on any platform – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal or WordPress without an export. Its pages become builder pages with their images, and the old addresses redirect to the new ones. The pages stay hidden until you check and publish them; the design is not copied – the pages take this site’s look.' => 'Zadejte adresu webu na jakékoli platformě – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal nebo WordPress bez exportu. Z jeho stránek se stanou stránky v builderu i s obrázky a staré adresy se přesměrují na nové. Stránky zůstanou skryté, dokud je nezkontrolujete a nezveřejníte; vzhled se nekopíruje – stránky převezmou vzhled tohoto webu.',
    'This server cannot download from other sites (both curl and allow_url_fopen are missing, or the GD extension).' => 'Tento server neumí stahovat z jiných webů (chybí curl i allow_url_fopen, nebo rozšíření GD).',
    'Address of the site' => 'Adresa webu',
    'Kaleta reads the sitemap, or follows the site’s links when there is none – at most %s pages.' => 'Kaleta přečte mapu webu (sitemap), a když chybí, projde odkazy webu – nejvýš %s stránek.',
    'the main language' => 'hlavní jazyk',
    'Download the images into Media' => 'Stáhnout obrázky do Médií',
    'Redirect the old addresses to the new pages' => 'Přesměrovat staré adresy na nové stránky',
    'Import blog posts as news (addresses like /blog/…, or with a publication date)' => 'Články blogu importovat jako novinky (adresy jako /blog/… nebo s datem zveřejnění)',
    'Find the pages' => 'Najít stránky',
    'finding pages' => 'hledají se stránky',
    'Remove from the list' => 'Odebrat ze seznamu',
    'Enter the address of the site, e.g. https://www.example.com.' => 'Zadejte adresu webu, např. https://www.example.com.',
    'The import does not exist any more.' => 'Tento import už neexistuje.',
    'Site: %s' => 'Web: %s',
    'Finding pages: %s found so far. Keep this page open, it continues by itself.' => 'Hledají se stránky: zatím nalezeno %s. Nechte stránku otevřenou, pokračuje sama.',
    'No pages were found. Check the address – the site has to be reachable from this server.' => 'Nenašly se žádné stránky. Zkontrolujte adresu – web musí být z tohoto serveru dostupný.',
    '%s pages found. They will be imported as hidden pages; nothing changes for visitors until you publish them.' => 'Nalezeno stránek: %s. Naimportují se jako skryté; pro návštěvníky se nic nezmění, dokud je nezveřejníte.',
    '… and %s more.' => '… a dalších %s.',
    'Import %s pages' => 'Importovat stránky (%s)',
    'Importing: %s of %s pages. Keep this page open, it continues by itself.' => 'Import: %s z %s stránek. Nechte stránku otevřenou, pokračuje sama.',
    'The import is finished. The pages are hidden until you check and publish them.' => 'Import je hotový. Stránky jsou skryté, dokud je nezkontrolujete a nezveřejníte.',
    'Images in Media' => 'Obrázky v Médiích',
    '%s pages could not be imported' => 'Nepodařilo se naimportovat stránek: %s',
    'Next: check the pages, put the ones you keep into the menu and publish them. Claude can match their look to the design system and tidy the texts through the connection.' => 'Dál: zkontrolujte stránky, ty, které si necháte, dejte do menu a zveřejněte. Claude přes napojení sladí jejich vzhled s design systémem a upraví texty.',
    'Show pages' => 'Zobrazit stránky',
    'The page could not be downloaded.' => 'Stránku se nepodařilo stáhnout.',
    'The page has no content to import.' => 'Stránka nemá obsah k importu.',
    'Address of the old site' => 'Adresa starého webu',
    'Before you point the domain to this site, check the old site against it: every old address must lead somewhere, and no page may lose its search engine description, its form or most of its images. Nothing is changed – the check only reads.' => 'Než doménu nasměrujete na tento web, porovnejte s ním starý web: každá stará adresa musí někam vést a žádná stránka nesmí přijít o popis pro vyhledávače, formulář ani většinu obrázků. Nic se nemění – kontrola jen čte.',
    'Check the move' => 'Zkontrolovat přechod',
    'Check the move before going live' => 'Kontrola přechodu před spuštěním',
    'Checking: %s of %s addresses. Keep this page open, it continues by itself.' => 'Kontroluji: %s z %s adres. Nechte stránku otevřenou, pokračuje sama.',
    'Everything moved: every old address leads to a published page and nothing was lost.' => 'Všechno se přeneslo: každá stará adresa vede na zveřejněnou stránku a nic se neztratilo.',
    'Finding the pages of the old site. Keep this page open, it continues by itself.' => 'Hledám stránky starého webu. Nechte stránku otevřenou, pokračuje sama.',
    'Fix what is missing – redirects in Redirects, descriptions and forms on the pages – and check again. Claude can do it through the connection (migration_report).' => 'Doplňte, co chybí – přesměrování v Přesměrováních, popisy a formuláře na stránkách – a zkontrolujte znovu. Claude to zvládne přes napojení (migration_report).',
    'Missing' => 'Chybí',
    'Nearly ready: check the warnings below.' => 'Skoro hotovo: projděte upozornění níže.',
    'Not published yet' => 'Zatím nezveřejněné',
    'Not ready to go live: %s problems would cost visitors or search engines something.' => 'Ještě ne ke spuštění: %s problémů by návštěvníky nebo vyhledávače o něco připravilo.',
    'Nothing at this address and no redirect – it will end in 404.' => 'Na této adrese nic není a nevede z ní přesměrování – skončí chybou 404.',
    'OK' => 'V pořádku',
    'Old addresses' => 'Staré adresy',
    'Old site: %s' => 'Starý web: %s',
    'On this site' => 'Na tomto webu',
    'Problems' => 'Problémy',
    'Redirected' => 'Přesměrováno',
    'Redirected more than once – point the redirect straight at the final page.' => 'Přesměrováno víckrát – namiřte přesměrování rovnou na cílovou stránku.',
    'Redirected to another site.' => 'Přesměrováno na jiný web.',
    'Same address' => 'Stejná adresa',
    'The Redirects extension is off: no redirect from an old address works.' => 'Rozšíření Přesměrování je vypnuté: žádné přesměrování ze staré adresy nefunguje.',
    'The new page has less than half of the old page’s images.' => 'Nová stránka má méně než polovinu obrázků staré stránky.',
    'The old page could not be read, so only the address was checked.' => 'Starou stránku nešlo načíst, zkontrolovala se jen adresa.',
    'The old page had a form, the new one has none.' => 'Stará stránka měla formulář, nová žádný nemá.',
    'The old page had a search engine description, the new one has none.' => 'Stará stránka měla popis pro vyhledávače, nová ho nemá.',
    'The page is here but not published yet.' => 'Stránka tu je, ale ještě není zveřejněná.',
    'The report does not exist any more.' => 'Kontrola už neexistuje.',
    'check in progress' => 'kontrola probíhá',
    'Note' => 'Poznámka',
    'slide in from the left' => 'vyjetí zleva',
    'slide in from the right' => 'vyjetí zprava',
    'from a blur' => 'z rozostření',
    'Motion while scrolling' => 'Pohyb při rolování',
    'parallax (slower than the page)' => 'paralaxa (pomaleji než stránka)',
    'stronger parallax' => 'výraznější paralaxa',
    'slight rotation' => 'mírné natočení',
    'grows into view' => 'zvětšení při objevení',
    'Effect on hover' => 'Efekt po najetí myší',
    'lift with a shadow' => 'nadzvednout se stínem',
    'grow slightly' => 'mírně zvětšit',
    'nudge to the side' => 'posunout do strany',
    'fade a little' => 'trochu zprůhlednit',
    'SEO plugin %s: %s custom titles, %s meta descriptions, %s noindex – they go into the SEO fields of the news items and pages. A title made only of the plugin’s variables is skipped; the site builds it itself.' => 'SEO plugin %s: %s vlastních titulků, %s meta popisů, %s noindex – jdou do SEO polí novinek a stránek. Titulek složený jen z proměnných pluginu se přeskočí; web si ho sestaví sám.',
    'Canonical URLs (%s) are not transferred.' => 'Kanonické adresy (%s) se nepřenášejí.',
    'Redirects managed by SEO plugins (SmartCrawl, Yoast SEO, Rank Math) are not part of the export – they come over separately.' => 'Přesměrování spravovaná SEO pluginy (SmartCrawl, Yoast SEO, Rank Math) nejsou součástí exportu – přenášejí se zvlášť.',
    'With an SEO title, description or noindex from a plugin' => 'Se SEO titulkem, popisem nebo noindex z pluginu',
    'Custom post type “%s”: %s items become a collection with item pages at /%s/…, with the fields %s.' => 'Vlastní typ obsahu „%s“: %s položek se stane kolekcí se stránkami položek na /%s/…, s poli %s.',
    'Left out (repeaters, galleries or relationships – Claude can move them by hand): %s.' => 'Vynechá se (opakovače, galerie a vazby – Claude je může přenést ručně): %s.',
    'custom post types as collections (%s)' => 'vlastní typy obsahu jako kolekce (%s)',
    'Collection items (custom post types), in %s new collections' => 'Položky kolekcí (vlastní typy obsahu), v %s nových kolekcích',
    'Excerpt' => 'Výtah',
    'none' => 'žádná',
    'Header on scroll (header part only)' => 'Záhlaví při rolování (jen část Záhlaví)',
    'transparent at the top, solid after scrolling' => 'nahoře průhledné, po odrolování plné',
    'smaller after scrolling' => 'po odrolování menší',
    'transparent at the top and smaller after scrolling' => 'nahoře průhledné a po odrolování menší',
    'Text colour while the header is transparent' => 'Barva textu, dokud je záhlaví průhledné',
    'as normal' => 'jako obvykle',
    'light (over a dark photo)' => 'světlá (nad tmavou fotkou)',
    'dark (over a light photo)' => 'tmavá (nad světlou fotkou)',
    'An icon shows before the text. The description and group columns (a group inside a submenu with its own items) appear in a mega menu – the Navigation element with “Submenu as a wide panel”.' => 'Ikona se ukáže před textem. Popis a sloupce skupin (skupina uvnitř podmenu s vlastními položkami) se zobrazí v mega menu – prvek Navigace s volbou „Podmenu jako široký panel“.',
    'Description (mega menu)' => 'Popis (mega menu)',
    'Into the group above (a column of the mega menu)' => 'Do skupiny nad ní (sloupec mega menu)',
    '%s (default language)' => '%s (výchozí jazyk)',
    'Nothing to copy.' => 'Není co kopírovat.',
    'The clipboard does not contain Kaleta elements.' => 'Schránka neobsahuje prvky Kalety.',
    'None of the elements could be inserted.' => 'Žádný z prvků se nepodařilo vložit.',
    '%d images still load from %s – replace them with files from this site’s Media.' => '%d obrázků se dál načítá z %s – nahraďte je soubory z Médií tohoto webu.',
    '%d images were left out – the media of the other site are not available here.' => '%d obrázků bylo vynecháno – média druhého webu tu nejsou dostupná.',
    '%s ends with error %d' => '%s končí chybou %d',
    '%s failed %d× in a row: %s' => '%s selhalo %d× za sebou: %s',
    '%s: %d problem(s) on the site' => '%s: %d problém(ů) na webu',
    '/%s was requested %d times and there is no page or redirect.' => '/%s se hledalo %d×, ale není tam stránka ani přesměrování.',
    'Alert e-mails' => 'Upozornění e-mailem',
    'Alerts' => 'Upozornění',
    'Automatic backup %s' => 'Automatická záloha %s',
    'Background jobs' => 'Úlohy na pozadí',
    'Checking links' => 'Kontrola odkazů',
    'Deleting old personal data and events' => 'Mazání starých osobních údajů a událostí',
    'Details are in Settings → System status:' => 'Podrobnosti najdete v Nastavení → Stav systému:',
    'E-mail “%s” could not be sent: %s' => 'E-mail „%s“ se nepodařilo odeslat: %s',
    'Form “%s” sent from %s' => 'Formulář „%s“ odeslán z %s',
    'Installing version %s failed: %s' => 'Instalace verze %s selhala: %s',
    'Job' => 'Úloha',
    'Kaleta noticed something that needs your attention:' => 'Kaleta si všimla něčeho, co potřebuje vaši pozornost:',
    'Last run' => 'Naposledy',
    'Off-site copy of the media' => 'Kopie médií mimo server',
    'Problems in the last 7 days' => 'Problémy za posledních 7 dní',
    'Published: %s' => 'Zveřejněno: %s',
    'Runs' => 'Spouští se',
    'Scheduled publishing and announcements' => 'Plánované zveřejnění a oznámení',
    'Sending e-mail' => 'Odesílání e-mailů',
    'Sending newsletters' => 'Odesílání newsletterů',
    'Subscribers to the mailing service' => 'Odběratelé do mailingové služby',
    'The automatic backup failed: %s' => 'Automatická záloha selhala: %s',
    'The background job “%s” failed %d times in a row: %s' => 'Úloha na pozadí „%s“ selhala %d× za sebou: %s',
    'The background job “%s” works again.' => 'Úloha na pozadí „%s“ zase funguje.',
    'The look was published: %s' => 'Vzhled byl zveřejněn: %s',
    'The off-site copy of the backup failed: %s' => 'Kopie zálohy mimo server selhala: %s',
    'Version %s did not work (%s), so the site went back to version %s.' => 'Verze %s nefungovala (%s), web se proto vrátil k verzi %s.',
    'Version %s was installed (from %s).' => 'Nainstalována verze %s (z %s).',
    'Version %s was installed but the site did not work afterwards (%s). The website files have been returned to their state before the update.' => 'Verze %s se nainstalovala, ale web potom nefungoval (%s). Soubory webu se vrátily do stavu před aktualizací.',
    'Webhook %s could not be delivered: %s' => 'Webhook %s se nepodařilo doručit: %s',
    'Webhook deliveries' => 'Doručování webhooků',
    'When a backup, an update, e-mail, a webhook or a background job fails, the site sends one e-mail – at most one an hour, with everything that happened.' => 'Když selže záloha, aktualizace, e-mail, webhook nebo úloha na pozadí, web pošle jeden e-mail – nejvýš jeden za hodinu, se vším, co se stalo.',
    'You get at most one such e-mail an hour. Change the address or switch the alerts off in System status.' => 'Takový e-mail dostanete nejvýš jednou za hodinu. Adresu změníte nebo upozornění vypnete ve Stavu systému.',
    'cron and visits' => 'cron i návštěvy',
    'every %s' => 'každých %s',
    'every job worked the last time it ran' => 'každá úloha při posledním spuštění fungovala',
    'failed %d×' => 'selhalo %d×',
    'not run yet' => 'zatím neproběhlo',
    'ok' => 'v pořádku',
    'only from cron' => 'jen z cronu',
    'the administration' => 'administrace',
    'the home page' => 'úvodní stránka',
    'the site does not start' => 'web se nespustí',
    'Send alert e-mails' => 'Posílat upozornění e-mailem',
    'Send them to' => 'Posílat na',
    'Empty = the site e-mail (Settings → General).' => 'Prázdné = e-mail webu (Nastavení → Obecné).',
    '%s was blocked for %d hours after probing for other systems (%s).' => '%s je na %d h zablokovaná, protože zkoušela adresy jiných systémů (%s).',
    '0 = no limit. 120 is plenty for people; it stops aggressive scrapers.' => '0 = bez limitu. Lidem stačí 120; zastaví to agresivní stahovače.',
    'An address that asks for /wp-login.php, /.env and similar addresses of other systems 5 times in an hour is blocked for 24 hours.' => 'Adresa, která se během hodiny pětkrát zeptá na /wp-login.php, /.env a podobné adresy jiných systémů, se na 24 hodin zablokuje.',
    'Block probing' => 'Blokovat zkoušení',
    'Blocked addresses and networks' => 'Blokované adresy a sítě',
    'Blocked countries' => 'Blokované země',
    'Blocked for a while' => 'Dočasně zablokované',
    'Country: %s.' => 'Země: %s.',
    'Firewall on' => 'Firewall zapnutý',
    'No address is blocked right now.' => 'Teď není zablokovaná žádná adresa.',
    'Nothing refused yet.' => 'Zatím nic odmítnuto.',
    'One per line, e.g. 203.0.113.7 or 198.51.100.0/24; a comment after #.' => 'Jedna na řádek, např. 203.0.113.7 nebo 198.51.100.0/24; poznámka za #.',
    'Refused requests' => 'Odmítnuté požadavky',
    'Requests per minute from one address' => 'Požadavků za minutu z jedné adresy',
    'The address is no longer blocked.' => 'Adresa už není blokovaná.',
    'The country of visitors is not known here – blocking countries works only behind Cloudflare or when the hosting sends the country.' => 'Zemi návštěvníků tu neznáme – blokování zemí funguje jen za Cloudflare, nebo když zemi posílá hosting.',
    'The firewall guards the public site and the Claude connection – never the administration, so you cannot lock yourself out. Addresses of your local network are never blocked.' => 'Firewall chrání veřejný web a napojení Clauda – nikdy administraci, takže se nemůžete zamknout. Adresy vaší místní sítě se neblokují nikdy.',
    'The last 50; the log keeps 30 days.' => 'Posledních 50; záznam se drží 30 dní.',
    'The site runs behind' => 'Web běží za',
    'These lines are not addresses and are ignored: %s' => 'Tyto řádky nejsou adresy a nepoužijí se: %s',
    'Two-letter codes separated by commas, e.g. RU, CN. Only when the country is known (see above).' => 'Dvoupísmenné kódy oddělené čárkou, např. RU, CN. Jen když je země známá (viz výše).',
    'Unblock' => 'Odblokovat',
    'Until' => 'Do',
    'Why' => 'Proč',
    'Your address as the site sees it: %s.' => 'Vaše adresa, jak ji vidí web: %s.',
    'blocked address' => 'blokovaná adresa',
    'blocked country' => 'blokovaná země',
    'blocked for a while' => 'dočasně zablokovaná',
    'nothing – visitors connect directly' => 'ničím – návštěvníci se připojují přímo',
    'probing for other systems' => 'zkoušení jiných systémů',
    'too many requests' => 'příliš mnoho požadavků',
    'Domain and mail' => 'Doména a pošta',
    'Checks' => 'Kontroly',
    'switched off in the public demo – no request leaves it' => 've veřejném demu vypnuto – žádný požadavek z něj neodchází',
    'not checked yet – the background jobs check it once a day, or use Check now below' => 'zatím nekontrolováno – úlohy na pozadí to kontrolují jednou denně, nebo použijte Zkontrolovat teď níže',
    'the site runs on a local address (%s) – the certificate, the domain registration and the mail DNS records are checked once it has its public address' => 'web běží na místní adrese (%s) – certifikát, registrace domény a DNS záznamy pošty se kontrolují, až bude mít veřejnou adresu',
    'Sending domain' => 'Odesílací doména',
    'no sender address – fill in the site e-mail (Settings → General) so the mail records can be checked' => 'chybí adresa odesílatele – vyplňte e-mail webu (Nastavení → Základní), aby šlo záznamy pošty zkontrolovat',
    'the DNS records of %s could not be read (the server did not get an answer from its resolver)' => 'DNS záznamy domény %s se nepodařilo přečíst (server nedostal odpověď od svého resolveru)',
    'SPF record' => 'Záznam SPF',
    '%s has no SPF record – receiving servers cannot tell that its mail is legitimate and often file it as spam. Add a TXT record on %s: %s' => '%s nemá záznam SPF – přijímající servery nepoznají, že je její pošta pravá, a často ji zařadí do spamu. Přidejte TXT záznam na %s: %s',
    'includes the SMTP server %s' => 'zahrnuje SMTP server %s',
    'does not seem to include the SMTP server %s; add %s (or the value your mail provider publishes)' => 'zřejmě nezahrnuje SMTP server %s; přidejte %s (nebo hodnotu, kterou uvádí váš poskytovatel pošty)',
    'DMARC record' => 'Záznam DMARC',
    '%s has no DMARC record – Gmail and Microsoft require it from senders. Add a TXT record on %s: %s' => '%s nemá záznam DMARC – Gmail a Microsoft ho od odesílatelů vyžadují. Přidejte TXT záznam na %s: %s',
    'policy p=none only reports; once the reports look right, move to p=quarantine' => 'politika p=none jen hlásí; až budou hlášení v pořádku, přejděte na p=quarantine',
    'DKIM signature' => 'Podpis DKIM',
    'no DKIM key found under the common selectors (%s). If your mail provider signs with another selector, all is well; otherwise turn DKIM signing on with the provider and publish its key in DNS' => 'pod běžnými selektory (%s) se klíč DKIM nenašel. Pokud váš poskytovatel pošty podepisuje jiným selektorem, je vše v pořádku; jinak u něj zapněte podepisování DKIM a zveřejněte jeho klíč v DNS',
    'key published under the selector %s' => 'klíč zveřejněný pod selektorem %s',
    'Certificate' => 'Certifikát',
    'could not be read from %s: %s' => 'nepodařilo se přečíst z %s: %s',
    'expires in %d days (%s)' => 'vyprší za %d dní (%s)',
    'expired %d days ago (%s) – browsers warn visitors away from the site' => 'vypršel před %d dny (%s) – prohlížeče návštěvníky od webu odrazují',
    'renew it, or check that the automatic renewal (Let’s Encrypt) still works' => 'obnovte ho, nebo zkontrolujte, že automatické obnovování (Let’s Encrypt) stále funguje',
    'Domain registration' => 'Registrace domény',
    'the expiry of %s could not be checked: %s' => 'platnost domény %s se nepodařilo ověřit: %s',
    '%s – the registry does not publish the expiry date; check it with your registrar' => '%s – registr datum vypršení nezveřejňuje; ověřte ho u svého registrátora',
    '%s expires in %d days (%s)' => '%s vyprší za %d dní (%s)',
    '%s expired %d days ago (%s)' => '%s vypršela před %d dny (%s)',
    'renew the domain with your registrar – an expired domain takes the site and its mail down' => 'prodlužte doménu u registrátora – s vypršelou doménou přestane fungovat web i pošta',
    'The sending domain %s has no SPF record – mail from the forms will land in spam. Add a TXT record: %s' => 'Odesílací doména %s nemá záznam SPF – pošta z formulářů skončí ve spamu. Přidejte TXT záznam: %s',
    'The sending domain %s has no DMARC record – Gmail and Microsoft require it. Add a TXT record on %s: %s' => 'Odesílací doména %s nemá záznam DMARC – Gmail a Microsoft ho vyžadují. Přidejte TXT záznam na %s: %s',
    'The site certificate expires in %d days – check that it renews.' => 'Certifikát webu vyprší za %d dní – zkontrolujte, že se obnoví.',
    'The site certificate has expired – browsers warn visitors away from the site.' => 'Certifikát webu vypršel – prohlížeče návštěvníky od webu odrazují.',
    'The domain %s expires in %d days – renew it with the registrar.' => 'Doména %s vyprší za %d dní – prodlužte ji u registrátora.',
    'The domain %s has expired – renew it with the registrar before someone else takes it.' => 'Doména %s vypršela – prodlužte ji u registrátora, než ji získá někdo jiný.',
    'The site runs on a local address – the certificate, the domain and the mail records are checked once it has its public address.' => 'Web běží na místní adrese – certifikát, doména a záznamy pošty se zkontrolují, až bude mít veřejnou adresu.',
    'The domain and mail check has run – the results are in the table above.' => 'Kontrola domény a pošty proběhla – výsledky jsou v tabulce výše.',
    'The mail DNS records (SPF, DMARC, DKIM), the site certificate and the domain registration have not been checked yet. The check runs once a day on its own; the results appear in the table above.' => 'DNS záznamy pošty (SPF, DMARC, DKIM), certifikát webu a registrace domény zatím nebyly zkontrolovány. Kontrola běží jednou denně sama; výsledky se objeví v tabulce výše.',
    'Last checked %s. The check runs once a day on its own; the results are in the table above.' => 'Naposledy zkontrolováno %s. Kontrola běží jednou denně sama; výsledky jsou v tabulce výše.',
    'Domain, certificate and mail records' => 'Doména, certifikát a záznamy pro poštu',
    'Real-user speed (Core Web Vitals)' => 'Rychlost u návštěvníků (Core Web Vitals)',
    'Measurements' => 'Měření',
    'good' => 'dobré',
    'needs improvement' => 'ke zlepšení',
    'poor' => 'špatné',
    'No measurements yet – they arrive from visitors’ browsers while the statistics are on.' => 'Zatím žádná měření – přicházejí z prohlížečů návštěvníků, dokud je statistika zapnutá.',
    'Speed: the 75th percentile of what real visitors experienced – loading of the main content (LCP, good up to 2.5 s), layout shifts (CLS, good up to 0.1) and the response to interaction (INP, good up to 200 ms); values are the upper edge of a histogram bucket, so they never flatter.' => 'Rychlost: 75. percentil toho, co zažili skuteční návštěvníci – načtení hlavního obsahu (LCP, dobré do 2,5 s), posuny rozložení (CLS, dobré do 0,1) a odezva na interakci (INP, dobré do 200 ms); hodnoty jsou horní hranicí přihrádky histogramu, nikdy tedy nelichotí.',
    'Loading got slower: visitors wait %s s for the main content (p75 LCP) in the last 30 days, %s s in the 30 days before (%d measurements) – check the images, fonts and embeds above the fold.' => 'Načítání se zpomalilo: návštěvníci čekají na hlavní obsah %s s (p75 LCP) za posledních 30 dní, %s s za 30 dní předtím (%d měření) – zkontrolujte obrázky, písma a vložený obsah v horní části stránky.',
    'Suspend automatically' => 'Pozastavovat automaticky',
    'block accounts nobody has used for %d days (never the last administrator)' => 'blokovat účty, které nikdo %d dní nepoužil (nikdy posledního správce)',
    'revoke Claude connections nobody has used for %d days' => 'zrušit napojení Clauda, která nikdo %d dní nepoužil',
    'Checked once a day. While this is off, System status and the site audit only report unused accounts and connections. A blocked account shows the reason in Users and an administrator can reactivate it; a revoked connection has to be connected again.' => 'Kontroluje se jednou denně. Dokud je to vypnuté, Stav systému a audit webu nepoužívané účty a napojení jen hlásí. Zablokovaný účet ukazuje důvod v Uživatelích a správce ho může znovu aktivovat; zrušené napojení je třeba připojit znovu.',
    'Accounts and access' => 'Účty a přístup',
    'Two-step sign-in for administrators' => 'Dvoufázové přihlášení správců',
    '%d administrator(s) sign in without two-step sign-in or a passkey – it is turned on under My account (avatar at the top right)' => '%d správce/správců se přihlašuje bez dvoufázového přihlášení nebo přihlašovacího klíče – zapíná se v Můj účet (avatar vpravo nahoře)',
    'Unused accounts' => 'Nepoužívané účty',
    'every account has been used in the last %d days' => 'každý účet byl za posledních %d dní použit',
    '%d account(s) unused for %d days – the automatic suspension blocks them on its next daily run' => '%d účet/účtů %d dní nepoužito – automatické pozastavení je zablokuje při dalším denním běhu',
    '%d account(s) unused for %d days – block them in Users, or switch on the automatic suspension in Settings → General' => '%d účet/účtů %d dní nepoužito – zablokujte je v Uživatelích, nebo zapněte automatické pozastavení v Nastavení → Základní',
    'last activity %s' => 'poslední aktivita %s',
    'Unused Claude connections' => 'Nepoužívaná napojení Clauda',
    'every connection has been used in the last %d days' => 'každé napojení bylo za posledních %d dní použito',
    '%d connection(s) unused for %d days – the automatic suspension revokes them on its next daily run' => '%d napojení %d dní nepoužito – automatické pozastavení je zruší při dalším denním běhu',
    '%d connection(s) unused for %d days – revoke them in the user’s account, or switch on the automatic suspension in Settings → General' => '%d napojení %d dní nepoužito – zrušte je u účtu uživatele, nebo zapněte automatické pozastavení v Nastavení → Základní',
    'Connections without an expiry' => 'Napojení bez omezení platnosti',
    'every personal token has an expiry date' => 'každý osobní token má omezenou platnost',
    '%d personal token(s) never expire – a token works until it is revoked; revoke those that are not needed, or create them again with an expiry' => '%d osobní token(y) nikdy nevyprší – token funguje, dokud ho nezrušíte; zrušte ty, které nejsou potřeba, nebo je vytvořte znovu s omezenou platností',
    '%d – blocked by an administrator or by the automatic suspension; you can reactivate them in Users' => '%d – zablokoval správce nebo automatické pozastavení; znovu aktivovat je můžete v Uživatelích',
    'Automatic suspension' => 'Automatické pozastavení',
    'off – unused accounts and connections are only reported (Settings → General)' => 'vypnuto – nepoužívané účty a napojení se jen hlásí (Nastavení → Základní)',
    'accounts after %d days' => 'účty po %d dnech',
    'Claude connections after %d days' => 'napojení Clauda po %d dnech',
    'The account %s has not been used for %d days (last activity %s) – block it, or let the automatic suspension do it.' => 'Účet %s nikdo %d dní nepoužil (poslední aktivita %s) – zablokujte ho, nebo to nechte na automatickém pozastavení.',
    'The Claude connection “%s” of %s has not been used for %d days – revoke it, or let the automatic suspension do it.' => 'Napojení Clauda „%s“ uživatele %s nikdo %d dní nepoužil – zrušte ho, nebo to nechte na automatickém pozastavení.',
    'Unused accounts and Claude connections are only reported – switch on the automatic suspension (Settings → General) so that leftover access closes itself.' => 'Nepoužívané účty a napojení Clauda se jen hlásí – zapněte automatické pozastavení (Nastavení → Základní), aby se zapomenutý přístup uzavřel sám.',
    'The account is not blocked.' => 'Účet není zablokovaný.',
    'The account has been reactivated – the user can sign in again.' => 'Účet je znovu aktivní – uživatel se může zase přihlásit.',
    'The connection has been revoked – Claude can no longer sign in with it.' => 'Napojení je zrušené – Claude se s ním už nepřihlásí.',
    'The connection no longer exists.' => 'Napojení už neexistuje.',
    'Blocked automatically on %s – nobody had used the account for %d days. An administrator can reactivate it.' => 'Zablokován automaticky %s – účet nikdo %d dní nepoužil. Správce ho může znovu aktivovat.',
    'blocked automatically' => 'zablokován automaticky',
    'Reactivate' => 'Znovu aktivovat',
    'Blocked automatically on %s – nobody had used the account for %d days. Untick the box and save to reactivate the account.' => 'Zablokován automaticky %s – účet nikdo %d dní nepoužil. Odškrtněte políčko a uložte, účet bude zase aktivní.',
    'Claude connections' => 'Napojení Clauda',
    'Personal tokens and connected applications of this account. A connection nobody has used for %d days is reported in System status; revoke what is not needed any more.' => 'Osobní tokeny a připojené aplikace tohoto účtu. Napojení, které nikdo %d dní nepoužil, hlásí Stav systému; zrušte, co už není potřeba.',
    'Revoke the connection? Claude will no longer be able to sign in with it.' => 'Zrušit napojení? Claude se s ním už nepřihlásí.',
    'personal token' => 'osobní token',
    'connected application' => 'připojená aplikace',
    'last used %s' => 'naposledy použito %s',
    'never used' => 'zatím nepoužito',
    'valid until %s' => 'platí do %s',
    'no expiry' => 'bez omezení platnosti',
    'Revoke' => 'Zrušit',
    'expired %s' => 'vypršel %s',
    'Valid for' => 'Platnost',
    '1 year' => '1 rok',
    '%d days' => '%d dní',
    'An expired token stops working on its own; you then create a new one. A token nobody uses for %d days is reported in System status.' => 'Token po vypršení přestane fungovat sám; pak si vytvoříte nový. Token, který nikdo %d dní nepoužije, hlásí Stav systému.',
    'connection revoked automatically' => 'napojení zrušeno automaticky',
    'account reactivated' => 'účet znovu aktivován',
    'connection revoked' => 'napojení zrušeno',
    'An account not used for %d days was suspended (user #%d).' => 'Účet nepoužitý %d dní byl pozastaven (uživatel č. %d).',
    'A Claude connection not used for %d days was revoked (user #%d).' => 'Napojení Clauda nepoužité %d dní bylo zrušeno (uživatel č. %d).',
    'Suspending unused accounts and connections' => 'Pozastavení nepoužívaných účtů a napojení',
    'Fleet console' => 'Konzole webů',
    'Makes this installation the console of your other Kaleta sites: they report to it every hour, it shows all of them on one screen sorted by what needs attention, checks that they are up and decides when they install a new version – test sites first, the rest two days later. It never gets into the sites.' => 'Udělá z této instalace konzoli vašich dalších webů na Kaletě: každou hodinu jí posílají hlášení, ukáže je všechny na jedné obrazovce seřazené podle toho, co potřebuje pozornost, hlídá, jestli běží, a rozhoduje, kdy nainstalují novou verzi – nejdřív testovací weby, ostatní o dva dny později. Do webů se nikdy nedostane.',
    '%s was paired with the console.' => '%s se spároval s konzolí.',
    '%s runs version %s.' => '%s běží na verzi %s.',
    '%s is no longer in the console.' => '%s už v konzoli není.',
    '%s answers again.' => '%s opět odpovídá.',
    '%s does not answer (%s).' => '%s neodpovídá (%s).',
    'no answer' => 'bez odpovědi',
    '%s has not sent its heartbeat for more than a day.' => '%s už víc než den neposlal hlášení.',
    'This is not a pairing key of a Kaleta console (it starts with kaleta-console:).' => 'Tohle není párovací klíč konzole Kalety (začíná kaleta-console:).',
    'Fill in the site address in Settings → General first.' => 'Nejdřív vyplňte adresu webu v Nastavení → Základní.',
    'The console refused the pairing: %s' => 'Konzole spárování odmítla: %s',
    'The site was paired with the fleet console %s.' => 'Web se spároval s konzolí webů %s.',
    'The new version is allowed on %d sites; each installs it with its next report (within an hour).' => 'Nová verze je povolená na %d webech; každý ji nainstaluje se svým dalším hlášením (do hodiny).',
    'The site is not in the console.' => 'Web v konzoli není.',
    'Saved.' => 'Uloženo.',
    'Checked.' => 'Zkontrolováno.',
    'The site was removed from the console. It stops reporting with its next report; pair it again to bring it back.' => 'Web je z konzole odebraný. Jeho další hlášení konzole odmítne; vrátíte ho novým spárováním.',
    'A fleet console is another Kaleta installation that shows all your sites on one screen. This site sends it a signed report every hour – version, health, background jobs, backups, enquiries waiting and visits, never names or the content of enquiries. The console cannot get into this site.' => 'Konzole webů je jiná instalace Kalety, která ukazuje všechny vaše weby na jedné obrazovce. Tento web jí každou hodinu pošle podepsané hlášení – verzi, stav, úlohy na pozadí, zálohy, poptávky čekající na odpověď a návštěvy, nikdy jména ani obsah poptávek. Konzole se do tohoto webu dostat nemůže.',
    'Pair with a console' => 'Spárovat s konzolí',
    'Pairing key' => 'Párovací klíč',
    'On the console: Fleet → Add a site. The key is valid for 24 hours and only once.' => 'V konzoli: Konzole webů → Přidat web. Klíč platí 24 hodin a jen jednou.',
    'The console decides when new versions install here' => 'O instalaci nových verzí tady rozhoduje konzole',
    'Test sites first, the rest two days later when nothing broke. Only versions signed by the Kaleta publisher install, as always.' => 'Nejdřív testovací weby, ostatní o dva dny později, když se nic nerozbilo. Instalují se jako vždy jen verze podepsané vydavatelem Kalety.',
    'Pair' => 'Spárovat',
    'Console' => 'Konzole',
    'Key fingerprints' => 'Otisky klíčů',
    'console %s, this site %s' => 'konzole %s, tento web %s',
    'Last report' => 'Poslední hlášení',
    'not sent yet' => 'zatím neodesláno',
    'Allowed update' => 'Povolená aktualizace',
    'Version %s – it installs with the next background run.' => 'Verze %s – nainstaluje se při dalším běhu úloh na pozadí.',
    'Without it, updates work as before: security releases install themselves when that is on in Backups and updates, others you install yourself.' => 'Bez toho fungují aktualizace jako dřív: bezpečnostní vydání se nainstalují sama, pokud je to zapnuté v Zálohách a aktualizacích, ostatní instalujete sami.',
    'Save the choice about updates' => 'Uložit volbu aktualizací',
    'Send a report now' => 'Poslat hlášení hned',
    'The site will stop reporting to the console. Continue?' => 'Web přestane posílat hlášení konzoli. Pokračovat?',
    'Disconnect from the console' => 'Odpojit od konzole',
    'Paste this pairing key on the site in Settings → Fleet console. It is valid for 24 hours and only once; it is not shown again.' => 'Vložte tento párovací klíč na webu do Nastavení → Konzole webů. Platí 24 hodin a jen jednou; znovu se už neukáže.',
    'No site reports to this console yet. Make a pairing key and paste it on the site.' => 'Této konzoli zatím žádný web nehlásí. Vytvořte párovací klíč a vložte ho na webu.',
    'All %d sites are fine.' => 'Všech %d webů je v pořádku.',
    '%d of %d sites need attention.' => '%d z %d webů potřebuje pozornost.',
    'The newest version: %s.' => 'Nejnovější verze: %s.',
    'Add a site' => 'Přidat web',
    'Check all now' => 'Zkontrolovat vše hned',
    'Every site that lets the console decide installs version %s within an hour, without waiting for the test sites. Continue?' => 'Každý web, který nechává rozhodovat konzoli, nainstaluje verzi %s do hodiny, bez čekání na testovací weby. Pokračovat?',
    'Allow the new version everywhere now' => 'Povolit novou verzi všude hned',
    'Which sites' => 'Které weby',
    'Need attention' => 'Potřebují pozornost',
    'All sites' => 'Všechny weby',
    'Nothing needs attention.' => 'Nic nepotřebuje pozornost.',
    'What needs attention' => 'Co potřebuje pozornost',
    'Version' => 'Verze',
    'Enquiries waiting' => 'Čekající poptávky',
    'test site' => 'testovací web',
    'allowed %s' => 'povoleno %s',
    'Sites report every hour; the console checks every 5 minutes that each home page answers. Problems reach you by the alert e-mail (Settings → System status → Alerts).' => 'Weby se hlásí každou hodinu; konzole každých 5 minut kontroluje, že úvodní stránka každého webu odpovídá. Problémy vám přijdou e-mailem s upozorněním (Nastavení → Stav systému → Upozornění).',
    'Administration of the site' => 'Administrace webu',
    'Needs attention:' => 'Potřebuje pozornost:',
    'not checked yet' => 'zatím nekontrolováno',
    'no report yet' => 'zatím bez hlášení',
    '%s is available' => 'k dispozici je %s',
    'Last update' => 'Poslední aktualizace',
    'failed' => 'selhala',
    'Health' => 'Stav',
    'Last backup' => 'Poslední záloha',
    'off-site copy: %s' => 'kopie mimo server: %s',
    'Cron last called' => 'Cron naposledy volal',
    'Visits in 7 days' => 'Návštěvy za 7 dní',
    '%d in 7 days, %d waiting for an answer' => '%d za 7 dní, %d čeká na odpověď',
    'no findings' => 'bez nálezů',
    'Problems the site reports' => 'Problémy, které web hlásí',
    'The site reports its problems in English; fix them in its administration.' => 'Web hlásí své problémy anglicky; opravíte je v jeho administraci.',
    'Background jobs that fail: %s' => 'Úlohy na pozadí, které selhávají: %s',
    'This site decides about its updates itself (Settings → Fleet console on the site).' => 'Tento web rozhoduje o svých aktualizacích sám (na webu v Nastavení → Konzole webů).',
    'Ring' => 'Okruh',
    'normal – after the test sites ran the version for 48 hours without problems' => 'běžný – až testovací weby poběží na verzi 48 hodin bez problémů',
    'test site – gets a new version first' => 'testovací web – dostane novou verzi jako první',
    'Security releases go to every site at once.' => 'Bezpečnostní vydání jdou na všechny weby hned.',
    'Save' => 'Uložit',
    'Allow version %s now' => 'Povolit verzi %s hned',
    'Remove the site from the console? Its reports will be refused until it is paired again.' => 'Odebrat web z konzole? Jeho hlášení se budou odmítat, dokud ho znovu nespárujete.',
    'Remove from the console' => 'Odebrat z konzole',
    'Events' => 'Události',
