    'The site no longer reports to the console.' => 'Web už konzoli nic nehlásí.',
    'Report to the fleet console' => 'Hlášení konzoli webů',
    'Fleet console: are the sites up' => 'Konzole webů: běží weby?',
    'Fleet' => 'Konzole webů',
    'The console did not confirm the report.' => 'Konzole hlášení nepotvrdila.',
    'The console does not know this site any more – pair it again.' => 'Konzole tento web už nezná – spárujte ho znovu.',
    'Monthly report' => 'Měsíční zpráva',
    'In the first days of each month the site e-mails a short report about the previous month: traffic, enquiries and sign-ups, updates, backups, changes made by people and by Claude, the problems right now and what needs your decision. Counts and page addresses only – never names, e-mail addresses or the contents of enquiries, so the report can be forwarded. With the agency details from the General tab it carries the agency’s branding.' => 'V prvních dnech každého měsíce web pošle e-mailem krátkou zprávu o předchozím měsíci: návštěvnost, poptávky a přihlášení k odběru, aktualizace, zálohy, změny provedené lidmi i Claudem, aktuální problémy a co potřebuje vaše rozhodnutí. Jen počty a adresy stránek – nikdy jména, e-mailové adresy ani obsah poptávek, zprávu tak lze přeposlat. S údaji agentury ze záložky Základní nese značku agentury.',
    'Send a monthly report by e-mail' => 'Posílat měsíční zprávu e-mailem',
    'One address per line or separated by commas, at most 10. Empty = the site e-mail (Settings → General).' => 'Jedna adresa na řádek nebo oddělené čárkou, nejvýš 10. Prázdné = e-mail webu (Nastavení → Základní).',
    'Preview last month' => 'Náhled minulého měsíce',
    'Send last month’s report now' => 'Poslat zprávu za minulý měsíc teď',
    'Save the settings first – sending uses the saved recipients.' => 'Nejdřív nastavení uložte – odeslání použije uložené příjemce.',
    'There is nobody to send the report to – fill in the recipients, or the site e-mail on the General tab.' => 'Zprávu není komu poslat – vyplňte příjemce, nebo e-mail webu na záložce Základní.',
    'The report has been handed over for delivery to %d recipient(s).' => 'Zpráva byla předána k doručení %d příjemci (příjemcům).',
    'Monthly report by e-mail' => 'Měsíční zpráva e-mailem',
    'The monthly report for %s went to %d recipient(s).' => 'Měsíční zpráva za %s odešla %d příjemci (příjemcům).',
