    'Enquiries and sign-ups' => 'Poptávky a přihlášení',
    'none this month' => 'tento měsíc žádné',
    '%d made, %d failed' => '%d vytvořeno, %d selhalo',
    'the last one %s' => 'poslední %s',
    'Backups' => 'Zálohy',
