    'Changes in the administration' => 'Změny v administraci',
    'Care of the site' => 'Péče o web',
    'Problems right now' => 'Aktuální problémy',
    'None – every check in System status is fine.' => 'Žádné – všechny kontroly ve Stavu systému jsou v pořádku.',
    'Details are in Settings → System status' => 'Podrobnosti jsou v Nastavení → Stav systému',
    'Sent once a month by the website %s. Switch it off or change the recipients in Settings → Mail.' => 'Posílá jednou za měsíc web %s. Vypnout ji nebo změnit příjemce můžete v Nastavení → Pošta.',
    'The monthly report by e-mail went out (the month and how many recipients).' => 'Odešla měsíční zpráva e-mailem (měsíc a počet příjemců).',
    'The fact %s changed.' => 'Fakt %s se změnil.',
    'The key may contain lowercase letters, digits and _ and must start with a letter (2–40 characters).' => 'Klíč smí obsahovat malá písmena, číslice a _ a musí začínat písmenem (2–40 znaků).',
    'This fact comes from the settings (Settings → Company) – change it there.' => 'Tento fakt pochází z nastavení (Nastavení → Firma) – změňte ho tam.',
    'Create the fact in the default language first.' => 'Nejdřív fakt vytvořte ve výchozím jazyce.',
    'amount of money' => 'částka',
    'web address' => 'webová adresa',
    'founding date' => 'datum založení',
    'number of employees' => 'počet zaměstnanců',
    'price range' => 'cenová hladina',
    'area served' => 'obsluhovaná oblast',
    'award' => 'ocenění',
    'languages' => 'jazyky',
    'founder' => 'zakladatel',
    'number' => 'číslo',
    'date' => 'datum',
    'year' => 'rok',
    'phone' => 'telefon',
    'Company name' => 'Název firmy',
    'Current year' => 'Aktuální rok',
    'The fact is saved.' => 'Fakt je uložený.',
    'The fact does not exist.' => 'Fakt neexistuje.',
    'The fact is deleted.' => 'Fakt je smazaný.',
    'The fact is deleted – some content still uses it and shows nothing there now; the site audit lists it.' => 'Fakt je smazaný – nějaký obsah ho ještě používá a teď tam nic neukazuje; audit webu ho vypíše.',
    'Write a fact once and use it everywhere: {{fact.key}} in a text, a button or a link (tel:{{fact.company_phone}}). The site fills in the value when a page is shown; change it here and every page says the new value.' => 'Fakt zapíšete jednou a použijete všude: {{fact.klic}} v textu, tlačítku nebo odkazu (tel:{{fact.company_phone}}). Web hodnotu doplní při zobrazení stránky; změníte ji tady a každá stránka řekne novou hodnotu.',
    'New fact' => 'Nový fakt',
    'Sentences with numbers that are not facts yet' => 'Věty s čísly, které ještě nejsou fakty',
    'No facts yet. Typical ones: the year the company was founded, the number of projects or clients, a price from, the warranty, the area you serve.' => 'Zatím žádné fakty. Typicky: rok založení firmy, počet zakázek nebo klientů, cena od, záruka, oblast, kde působíte.',
    'Fact' => 'Fakt',
    'Value' => 'Hodnota',
    'Token' => 'Značka',
    'Used' => 'Použito',
    'Changed' => 'Změněno',
    'From the settings' => 'Z nastavení',
    'not filled in' => 'nevyplněno',
    'The company details are changed in Settings → Company. Claude reads and changes facts with list_facts and save_fact.' => 'Údaje o firmě se mění v Nastavení → Firma. Claude fakty čte a mění nástroji list_facts a save_fact.',
    'All facts' => 'Všechny fakty',
    'No text on the site states the old value “%s” any more.' => 'Žádný text na webu už starou hodnotu „%s“ neuvádí.',
    'The old value “%s” is still written as plain text in %d places – replace it with the token so it changes by itself next time:' => 'Stará hodnota „%s“ je ještě napsaná jako prostý text na %d místech – nahraďte ji značkou, ať se příště změní sama:',
    'e.g. Founded' => 'např. Založeno',
    'Lowercase letters, digits and _. In content: {{fact.key}}. It cannot change later.' => 'Malá písmena, číslice a _. V obsahu: {{fact.klic}}. Později už změnit nejde.',
    'Type' => 'Typ',
    'A number is shown with the thousands separator of the language, a date in its format, an amount as 1 500 CZK (enter 1500 CZK).' => 'Číslo se ukáže s oddělovačem tisíců podle jazyka, datum v jeho formátu, částka jako 1 500 CZK (zadejte 1500 CZK).',
    'Empty = the same as the default value.' => 'Prázdné = stejné jako výchozí hodnota.',
    'For search engines' => 'Pro vyhledávače',
    'Adds the fact to the company in the structured data (schema.org) search engines and AI assistants read.' => 'Přidá fakt k firmě do strukturovaných dat (schema.org), která čtou vyhledávače a AI asistenti.',
    'Where the number comes from – for you and your colleagues, not shown on the site.' => 'Odkud číslo pochází – pro vás a kolegy, na webu se neukazuje.',
    'Delete the fact? Content that uses it will show nothing in its place.' => 'Smazat fakt? Obsah, který ho používá, na jeho místě nic neukáže.',
    'Delete' => 'Smazat',
    'Not used yet. Write {{fact.%s}} into a text, a button or a link.' => 'Zatím se nepoužívá. Napište {{fact.%s}} do textu, tlačítka nebo odkazu.',
    'Changes' => 'Změny',
    'Sentences with numbers, years and amounts written as plain text. When one of them changes – a new year, another project – you have to find every place yourself. Make it a fact and write {{fact.key}} instead.' => 'Věty s čísly, roky a částkami napsanými jako prostý text. Když se některé změní – nový rok, další zakázka – musíte každé místo najít sami. Udělejte z nich fakt a napište místo nich {{fact.klic}}.',
    'No such sentences – the numbers on the site are facts already.' => 'Žádné takové věty – čísla na webu už jsou fakty.',
    'Sentence' => 'Věta',
    'Facts' => 'Fakty',
    'The value does not fit the type of the fact (%s).' => 'Hodnota neodpovídá typu faktu (%s).',
    'The fact {{fact.%s}} does not exist – visitors see nothing in its place. Create it in Facts, or fix the key.' => 'Fakt {{fact.%s}} neexistuje – návštěvníci na jeho místě nic neuvidí. Vytvořte ho ve Faktech, nebo opravte klíč.',
    'Open now (and until when)' => 'Otevřeno teď (a do kdy)',
    'Exceptions to the opening hours' => 'Výjimky z otevírací doby',
    'Holidays, a closed day, shorter hours. The site shows them under the opening hours, knows whether it is open now, and shows a notice bar a few days ahead until the exception ends.' => 'Svátky, zavřený den, kratší otevírací doba. Web je ukáže pod otevírací dobou, ví, jestli je právě otevřeno, a pár dní předem až do konce výjimky ukáže oznamovací lištu.',
    'notice %d days ahead' => 'oznámení %d dní předem',
    'no notice' => 'bez oznámení',
    'From' => 'Od',
    'One day: fill in only the first date.' => 'Jeden den: vyplňte jen první datum.',
    'Closed' => 'Zavřeno',
    'Closed all day' => 'Celý den zavřeno',
    'Or open' => 'Nebo otevřeno',
    'When it is open with different hours: uncheck Closed and enter the hours, more ranges with a comma.' => 'Když je otevřeno v jiných časech: zrušte Zavřeno a zadejte hodiny, víc rozsahů oddělte čárkou.',
    'e.g. Christmas' => 'např. Vánoce',
    'Notice bar' => 'Oznamovací lišta',
    'days ahead' => 'dní předem',
    '0 = no notice bar.' => '0 = bez oznamovací lišty.',
    'Add the exception' => 'Přidat výjimku',
    'The exception is saved.' => 'Výjimka je uložená.',
    'The exception is deleted.' => 'Výjimka je smazaná.',
    'Enter the dates as YYYY-MM-DD; the last day must not be before the first one.' => 'Zadejte data jako RRRR-MM-DD; poslední den nesmí být před prvním.',
    'Enter the hours of the exception, e.g. 9:00-12:00 (more ranges with a comma), or mark the days as closed.' => 'Zadejte hodiny výjimky, např. 9:00-12:00 (víc rozsahů čárkou), nebo dny označte jako zavřené.',
    'closed' => 'zavřeno',
    'Open now, until %s' => 'Teď otevřeno, do %s',
    'Closed now' => 'Teď zavřeno',
    'Closed now, opens today at %s' => 'Teď zavřeno, otevíráme dnes v %s',
    'Closed now, opens tomorrow at %s' => 'Teď zavřeno, otevíráme zítra v %s',
    'Closed now, opens on %s at %s' => 'Teď zavřeno, otevíráme %s v %s',
    'item of another collection' => 'položka jiné kolekce',
    'Linked collection' => 'Propojená kolekce',
    'An item of another collection links two collections – a person to a branch, a reference to a service: choose the type and the linked collection. {{key}} shows the linked item\'s name, {{key_url}} its page. On the page of the linked item, a Collection list filtered by the field with the value {{seo}} lists everything linked to it.' => 'Položka jiné kolekce propojí dvě kolekce – člověka s pobočkou, referenci se službou: zvolte typ a propojenou kolekci. {{klic}} ukáže název propojené položky, {{klic_url}} její stránku. Na stránce propojené položky vypíše Výpis kolekce filtrovaný podle pole s hodnotou {{seo}} všechno, co je s ní propojené.',
    'Hidden items redirect to' => 'Skryté položky přesměrovat na',
    'When an item is hidden or deleted – a person who left, a product no longer sold – its page leads here (301) instead of “page not found”. Empty = page not found.' => 'Když je položka skrytá nebo smazaná – člověk, který odešel, výrobek, který už neprodáváte –, její stránka vede sem (301) místo „stránka nenalezena“. Prázdné = stránka nenalezena.',
    'The redirect of hidden items must be an address on the site (/team) or https://…' => 'Přesměrování skrytých položek musí být adresa na webu (/tym) nebo https://…',
    'Unknown template.' => 'Neznámá šablona.',
    'The collection was created – add the first items.' => 'Kolekce je vytvořená – přidejte první položky.',
    'New team (people)' => 'Nový tým (lidé)',
    'Photo, role, languages, phone, e-mail, absence and a page for each person; the page of someone who left leads to the team page.' => 'Fotka, role, jazyky, telefon, e-mail, nepřítomnost a stránka pro každého; stránka toho, kdo odešel, vede na stránku týmu.',
    'Languages' => 'Jazyky',
    'On leave' => 'Nepřítomnost',
    'About' => 'O mně',
    'E-mail signature: %s' => 'E-mailový podpis: %s',
    'Made from the record of %s in the look of your site. When the record or the site changes, open this page again and copy the signature anew.' => 'Vytvořeno ze záznamu %s ve vzhledu vašeho webu. Když se záznam nebo web změní, otevřete tuto stránku znovu a podpis zkopírujte nanovo.',
    'Copy signature' => 'Kopírovat podpis',
    'Back to the item' => 'Zpět na položku',
    'Plain-text version' => 'Verze v prostém textu',
    'For mail clients and places that take no formatting – the Copy button puts it on the clipboard together with the formatted signature.' => 'Pro poštovní programy a místa bez formátování – tlačítko Kopírovat ji dá do schránky spolu s formátovaným podpisem.',
    'Where to paste it' => 'Kam ho vložit',
    'Settings (the gear) → See all settings → General → Signature → Create new, paste the signature into the box (Ctrl+V, on a Mac ⌘V) and click Save Changes at the bottom.' => 'Nastavení (ozubené kolo) → Zobrazit všechna nastavení → Obecné → Podpis → Vytvořit nový, podpis vložte do pole (Ctrl+V, na Macu ⌘V) a dole klikněte na Uložit změny.',
    'New message → Signature → Signatures… (Outlook on the web: Settings → Mail → Compose and reply), paste the signature and save.' => 'Nová zpráva → Podpis → Podpisy… (Outlook na webu: Nastavení → Pošta → Vytváření a odpovídání), podpis vložte a uložte.',
    'Mail → Settings → Signatures, choose the account, click +, paste the signature and untick “Always match my default message font”.' => 'Mail → Nastavení → Podpisy, vyberte účet, klikněte na +, podpis vložte a odškrtněte „Vždy použít výchozí písmo zprávy“.',
    'The photo and the logo load from your website, so they show as long as they stay there.' => 'Fotka a logo se načítají z vašeho webu, takže se zobrazují, dokud tam zůstanou.',
    'E-mail signature' => 'E-mailový podpis',
];
